

  // --- CORE TOAST NOTIFICATION ENGINE ---
  function showToast(msg, duration = 4000) {
    let toastContainer = document.getElementById('cabellaToastContainer');
    if (!toastContainer) {
      toastContainer = document.createElement('div');
      toastContainer.id = 'cabellaToastContainer';
      toastContainer.style.cssText = 'position:fixed; top:20px; right:20px; z-index:999999; display:flex; flex-direction:column; gap:10px; pointer-events:none; max-width:420px; width:calc(100% - 40px);';
      document.body.appendChild(toastContainer);
    }
    const toast = document.createElement('div');
    toast.style.cssText = 'background:#0f172a; color:#ffffff; padding:12px 18px; border-radius:10px; font-size:13.5px; font-weight:700; box-shadow:0 10px 25px -5px rgba(0,0,0,0.3), 0 0 0 1px rgba(255,255,255,0.1); display:flex; align-items:center; justify-content:space-between; gap:12px; pointer-events:auto; font-family: Roboto, Arial, sans-serif; line-height:1.4; border-left:4px solid #0284c7;';
    toast.innerHTML = `<div style="flex:1">${msg}</div><button onclick="this.parentElement.remove()" style="background:none; border:0; color:#94a3b8; font-size:16px; cursor:pointer; padding:0 4px; line-height:1">✕</button>`;
    toastContainer.appendChild(toast);
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transform = 'translateY(-10px)';
      toast.style.transition = 'all 0.3s ease-out';
      setTimeout(() => toast.remove(), 300);
    }, duration);
  }

  // --- SYSTEM AUDIT LOG ENGINE ---
  function getAuditLogs() {
    try {
      const raw = localStorage.getItem('cabella_audit_logs_v1');
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    return [
      { timestamp: new Date(Date.now() - 3600000 * 2).toISOString(), user: 'Gil Sirimarco', role: 'CFO', action: 'PORTAL_STARTUP', details: 'CabellaCSE Command Center initialized and secure session verified' },
      { timestamp: new Date(Date.now() - 3600000).toISOString(), user: 'Edwin Portillo', role: 'CEO', action: 'DISPATCH_VERIFY', details: 'Verified Saturday delivery manifest (21 Stops: 13 ALL IN, 7 Chavez, 1 Hotshot)' },
      { timestamp: new Date(Date.now() - 1800000).toISOString(), user: 'Mayra Rodriguez', role: 'Orders', action: 'INVENTORY_CHECK', details: 'Monitored SKU B12 depletion alert (~5.1 days left)' }
    ];
  }

  function logAuditEvent(action, details, metadata = {}) {
    try {
      const logs = getAuditLogs();
      const newEntry = {
        timestamp: new Date().toISOString(),
        user: (currentActiveUser && currentActiveUser.name) ? currentActiveUser.name : 'System User',
        role: (currentActiveUser && currentActiveUser.role) ? currentActiveUser.role : 'Staff',
        action: String(action || 'ACTION').toUpperCase(),
        details: String(details || ''),
        metadata: metadata
      };
      logs.unshift(newEntry);
      if (logs.length > 150) logs.pop();
      localStorage.setItem('cabella_audit_logs_v1', JSON.stringify(logs));
    } catch (e) {
      console.warn('Audit logging failed:', e);
    }
  }

  function openAuditLogModal() {
    const logs = getAuditLogs();
    let rowsHtml = '';
    logs.forEach(l => {
      const dateStr = new Date(l.timestamp).toLocaleString();
      let badgeBg = '#e2e8f0', badgeColor = '#0f172a';
      if (l.action.includes('DISPATCH') || l.action.includes('DELIVERY')) { badgeBg = '#e0f2fe'; badgeColor = '#0369a1'; }
      else if (l.action.includes('PROFILE') || l.action.includes('AUTH') || l.action.includes('SECURITY')) { badgeBg = '#fef3c7'; badgeColor = '#92400e'; }
      else if (l.action.includes('QBO') || l.action.includes('INVOICE') || l.action.includes('BATCH')) { badgeBg = '#dcfce7'; badgeColor = '#166534'; }
      else if (l.action.includes('REFRESH')) { badgeBg = '#f1f5f9'; badgeColor = '#475569'; }

      rowsHtml += `
        <tr style="border-bottom:1px solid #e2e8f0; font-size:12.5px">
          <td style="padding:10px 12px; color:#64748b; white-space:nowrap">${esc(dateStr)}</td>
          <td style="padding:10px 12px; font-weight:700; color:#0f172a">${esc(l.user)} <span style="font-size:10.5px; color:#64748b">(${esc(l.role)})</span></td>
          <td style="padding:10px 12px">
            <span style="background:${badgeBg}; color:${badgeColor}; font-weight:800; font-size:10.5px; padding:3px 8px; border-radius:4px">${esc(l.action)}</span>
          </td>
          <td style="padding:10px 12px; color:#334155">${esc(l.details)}</td>
        </tr>
      `;
    });

    const modalContent = `
      <div style="font-family:Roboto,Arial,sans-serif">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; padding-bottom:12px; border-bottom:1px solid #e2e8f0">
          <div>
            <h3 style="margin:0; font-size:18px; font-weight:800; color:#0f172a">📜 Security & Operations Audit Trail</h3>
            <p style="margin:2px 0 0; font-size:12.5px; color:#64748b">Complete chronological log of user role switches, data synchronizations, and operational actions.</p>
          </div>
          <button onclick="exportAuditLogCsv()" class="btn secondary" style="font-size:12px; padding:6px 12px; font-weight:700">📥 Export CSV</button>
        </div>
        <div style="max-height:480px; overflow-y:auto; border:1px solid #cbd5e1; border-radius:8px">
          <table style="width:100%; border-collapse:collapse; text-align:left">
            <thead style="background:#f8fafc; border-bottom:2px solid #cbd5e1; position:sticky; top:0">
              <tr style="font-size:11.5px; font-weight:800; color:#475569; text-transform:uppercase">
                <th style="padding:10px 12px">Timestamp</th>
                <th style="padding:10px 12px">User & Role</th>
                <th style="padding:10px 12px">Action Event</th>
                <th style="padding:10px 12px">Details</th>
              </tr>
            </thead>
            <tbody>
              ${rowsHtml}
            </tbody>
          </table>
        </div>
        <div style="margin-top:16px; display:flex; justify-content:space-between; align-items:center">
          <span style="font-size:12px; color:#64748b">Total Entries: <strong>${logs.length}</strong></span>
          <button onclick="closeModal()" class="btn" style="background:#0f172a; color:#fff; font-weight:700; padding:8px 18px; border-radius:6px; border:0; cursor:pointer">Close</button>
        </div>
      </div>
    `;
    showModal('Security Audit Trail', modalContent, '820px');
  }

  function exportAuditLogCsv() {
    const logs = getAuditLogs();
    let csv = 'Timestamp,User,Role,Action,Details\n';
    logs.forEach(l => {
      csv += `"${l.timestamp}","${(l.user||'').replace(/"/g, '""')}","${(l.role||'').replace(/"/g, '""')}","${(l.action||'').replace(/"/g, '""')}","${(l.details||'').replace(/"/g, '""')}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Cabella_Audit_Log_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
    showToast('📥 Audit Log exported to CSV.');
  }

  // --- DATA FRESHNESS & REAL-TIME SYNC ENGINE ---
  window.lastDataRefreshTime = new Date();

  function updateDataFreshnessUI() {
    const badge = document.getElementById('dataFreshnessBadge');
    if (!badge) return;
    const now = new Date();
    const diffSec = Math.floor((now - window.lastDataRefreshTime) / 1000);
    let text = 'Synced Just Now';
    if (diffSec >= 3600) {
      const hours = Math.floor(diffSec / 3600);
      text = `Synced ${hours}h ago`;
    } else if (diffSec >= 60) {
      const mins = Math.floor(diffSec / 60);
      text = `Synced ${mins}m ago`;
    }
    badge.innerHTML = `🟢 ${text}`;
  }
  setInterval(updateDataFreshnessUI, 30000);

  function refreshAllPortalData() {
    window.lastDataRefreshTime = new Date();
    updateDataFreshnessUI();
    if (typeof updateHomeDispatchSummary === 'function') updateHomeDispatchSummary();
    if (typeof updateHomeCommandCenterDepletion === 'function') updateHomeCommandCenterDepletion();
    if (typeof renderAllDispatchViews === 'function') renderAllDispatchViews();
    if (typeof renderActionNeededPanel === 'function') renderActionNeededPanel();
    if (typeof renderRoleBasedHomeModule === 'function') renderRoleBasedHomeModule();
    if (typeof updateRoleBasedFinancialVisibility === 'function') updateRoleBasedFinancialVisibility();
    logAuditEvent('DATA_REFRESH', 'Manual data refresh initiated across all modules');
    showToast('🔄 Portal data and operational stores refreshed successfully!');
  }

