  // --- CSV EXPORT UTILITIES ---
  function exportQboInvoicesCsv() {
    const invoices = [
      { num: 'INV-2026-881', client: 'Desert Star Homes LLC', job: '3555 W Reno Ave - Unit 4B', date: '2026-08-14', amount: '8450.00', status: 'Unpaid' },
      { num: 'INV-2026-880', client: 'Red Rock Custom Builders', job: '8840 Summerlin Pkwy', date: '2026-08-13', amount: '14200.00', status: 'Paid' },
      { num: 'INV-2026-879', client: 'Vegas Modern Living', job: '102 Azure Mist Dr', date: '2026-08-12', amount: '5600.00', status: 'Unpaid' },
      { num: 'INV-2026-878', client: 'Silver State Contractors', job: '2240 E Sahara Ave', date: '2026-08-11', amount: '12800.00', status: 'Paid' },
      { num: 'INV-2026-877', client: 'Apex Premier Remodeling', job: '4110 S Rainbow Blvd', date: '2026-08-10', amount: '9300.00', status: 'Unpaid' }
    ];
    let csv = 'Invoice Number,Customer Name,Jobsite Address,Invoice Date,Amount,Status\n';
    invoices.forEach(i => {
      csv += `"${i.num}","${i.client}","${i.job}","${i.date}","${i.amount}","${i.status}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `Cabella_QBO_Invoices_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast('📥 Exported Cabella QBO Invoices CSV successfully!');
  }

