    const finishEl = document.getElementById('priceFinish');
    const resultsEl = document.getElementById('priceResults');
    const summaryCardsEl = document.getElementById('vendorCostSummaryCards');

    if (!resultsEl) return;

    const query = (qEl ? qEl.value : '').toLowerCase().trim();
    const catFilter = catEl ? catEl.value : '';
