  function renderVendorModalTableRows(items) {
    if (!items || items.length === 0) {
      return '<tr><td colspan="8" style="padding:20px; text-align:center; color:#64748b">No matching items found.</td></tr>';
    }

    return items.map((item, idx) => {
      const cost = Number(item.cost || 0);
      const tier1 = (cost * 1.18).toFixed(2);
      const tier2 = (cost * 1.28).toFixed(2);
      const tier3 = (cost * 1.38).toFixed(2);
      const bg = idx % 2 === 0 ? '#ffffff' : '#f8fafc';

      return `
        <tr style="background:${bg}; border-bottom:1px solid #e2e8f0; transition:background 0.1s">
          <td style="padding:8px 10px; font-weight:800; font-family:monospace; color:#0f172a">${esc(item.sku)}</td>
          <td style="padding:8px 10px">
            <div style="font-weight:700; color:#1e293b">${esc(item.name)}</div>
            <div style="font-size:11px; color:#64748b">${esc(item.note || item.cat || '')}</div>
          </td>
          <td style="padding:8px 10px; font-size:12px; color:#475569"><span class="badge" style="margin:0; font-size:10.5px">${esc(item.size || item.unit || 'Standard')}</span></td>
          <td style="padding:8px 10px; text-align:right; font-weight:900; color:#047857; background:#f0fdf4; font-size:13px">${cost.toFixed(2)}</td>
          <td style="padding:8px 10px; text-align:right; font-weight:700; color:#0369a1; background:#f0f9ff">${tier1}</td>
          <td style="padding:8px 10px; text-align:right; font-weight:700; color:#1d4ed8; background:#eff6ff">${tier2}</td>
          <td style="padding:8px 10px; text-align:right; font-weight:700; color:#7c3aed; background:#faf5ff">${tier3}</td>
          <td style="padding:8px 8px; text-align:center">
            <button class="btn secondary" style="padding:3px 7px; font-size:11px; border-radius:4px" onclick="openQuickCreateModal('quote', '${esc(item.sku)}')">+ Quote</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterVendorModalTable(q) {
    const query = (q || '').toLowerCase().trim();
    const filtered = currentVendorModalItems.filter(it => {
      if (!query) return true;
      const sku = (it.sku || '').toLowerCase();
      const name = (it.name || '').toLowerCase();
      const note = (it.note || '').toLowerCase();
      const cat = (it.cat || '').toLowerCase();
      return sku.includes(query) || name.includes(query) || note.includes(query) || cat.includes(query);
    });

    const tbody = document.getElementById('vendorModalTableBody');
    const countEl = document.getElementById('vendorModalItemCount');
    if (tbody) tbody.innerHTML = renderVendorModalTableRows(filtered);
    if (countEl) countEl.innerText = `${filtered.length} of ${currentVendorModalItems.length} items`;
  }

  function copyVendorPriceSheet() {
    if (!currentVendorModalItems || currentVendorModalItems.length === 0) return;
    let text = `=== ${currentVendorModalName.toUpperCase()} WHOLESALE PRICE LIST ===\n\n`;
    currentVendorModalItems.forEach(it => {
      text += `${it.sku} - ${it.name} | Cost: ${Number(it.cost).toFixed(2)} | T1: ${(it.cost * 1.18).toFixed(2)} | T2: ${(it.cost * 1.28).toFixed(2)} | T3: ${(it.cost * 1.38).toFixed(2)}\n`;
    });
    navigator.clipboard.writeText(text).then(() => {
      showToast(`📋 Copied ${currentVendorModalName} price sheet to clipboard!`);
    }).catch(() => {
      showToast('📋 Price sheet copied!');
    });
  }

  function exportVendorPriceSheetCSV() {
    if (!currentVendorModalItems || currentVendorModalItems.length === 0) return;
    let csv = 'SKU,Item Name,Category,Size / Unit,Wholesale Net Cost,Tier 1 Contractor (+18%),Tier 2 Investor (+28%),Tier 3 Retail (+38%),Notes\n';
    currentVendorModalItems.forEach(it => {
      const cost = Number(it.cost).toFixed(2);
      const t1 = (it.cost * 1.18).toFixed(2);
      const t2 = (it.cost * 1.28).toFixed(2);
      const t3 = (it.cost * 1.38).toFixed(2);
      csv += `"${it.sku}","${(it.name||'').replace(/"/g,'""')}","${it.cat||''}","${it.size||it.unit||''}","${cost}","${t1}","${t2}","${t3}","${(it.note||'').replace(/"/g,'""')}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Cabella_${currentVendorModalName.replace(/[^a-zA-Z0-9]/g, '_')}_PriceList.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast(`📥 Exported ${currentVendorModalName} Price Sheet CSV!`);
  }

