  // --- COMMUNICATIONS & SOUND ENGINE ---
  let isDispatchSoundMuted = false;
  function toggleMuteSound() {
    isDispatchSoundMuted = !isDispatchSoundMuted;
    const btn = document.getElementById('muteSoundBtn');
    if (btn) btn.textContent = isDispatchSoundMuted ? '🔇 Muted: ON' : '🔊 Muted: OFF';
    showToast(isDispatchSoundMuted ? '🔇 Dispatch notifications muted' : '🔊 Dispatch notifications unmuted');
  }

  function testSound() {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(587.33, ctx.currentTime);
      osc.frequency.setValueAtTime(880, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.3);
      showToast('🔔 Notification chime played!');
    } catch(e) {
      showToast('🔔 Audio test triggered');
    }
  }

  function switchWaMode(mode) {
    const hub = document.getElementById('waHubContainer');
    const frame = document.getElementById('waFrameContainer');
    const hubBtn = document.getElementById('waModeHubBtn');
    const frameBtn = document.getElementById('waModeFrameBtn');
    if (mode === 'frame') {
      if (hub) hub.style.display = 'none';
      if (frame) frame.style.display = 'block';
      if (hubBtn) hubBtn.className = 'btn secondary';
      if (frameBtn) frameBtn.className = 'btn primary';
    } else {
      if (hub) hub.style.display = 'block';
      if (frame) frame.style.display = 'none';
      if (hubBtn) hubBtn.className = 'btn primary';
      if (frameBtn) frameBtn.className = 'btn secondary';
    }
  }

  function showWaAppNotice() {
    showToast('📱 Use the In-App Driver Hub to log status or launch WhatsApp Web.');
  }

  function attachWaPhoto() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      if (e.target.files && e.target.files[0]) {
        showToast(`📸 Photo attached: ${e.target.files[0].name} (Proof of Delivery ready)`);
      }
    };
    input.click();
  }

  function sendWaMessage() {
    const input = document.getElementById('waMessageInput');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    const feed = document.getElementById('waFeedContainer') || document.getElementById('driverFeedList');
    if (feed) {
      const div = document.createElement('div');
      div.style.cssText = 'background:#f0fdf4; border:1px solid #bbf7d0; padding:10px 14px; border-radius:8px; margin-top:8px; font-size:13px';
      const uName = (typeof currentActiveUser !== 'undefined' && currentActiveUser.name) ? currentActiveUser.name : 'Dispatcher';
      div.innerHTML = `<strong>You (${uName}):</strong> ${esc(msg)} <span style="font-size:10.5px; color:#64748b; float:right">Just Now</span>`;
      feed.prepend(div);
    }
    input.value = '';
    showToast('📨 Driver dispatch update sent!');
  }

  function sendTeamMessage() {
    const input = document.getElementById('teamMessageInput');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    input.value = '';
    showToast(`💬 Team announcement posted: "${msg}"`);
  }

  // --- VENDOR SEARCH & DIRECTORY ---
  
  function renderVendors(q = '') {
    const query = (q || '').toLowerCase().trim();
    const vendorListEl = document.getElementById('vendorList');
    if (!vendorListEl) return;

    const vendors = (typeof BASE_DATA !== 'undefined' && BASE_DATA.vendors) ? BASE_DATA.vendors : [];
    
    const filtered = vendors.filter(v => {
      if (!query) return true;
      const name = (v.name || '').toLowerCase();
      const comp = (v.company || '').toLowerCase();
      const cat = (v.category || []).join(' ').toLowerCase();
      const addr = (v.address || '').toLowerCase();
      const phone = (v.phone || '').toLowerCase();
      const email = (v.email || '').toLowerCase();
      
      if (query === 'price sheet') return true;
      if (query === 'web catalog') return v.url || name.includes('homeco') || name.includes('grandwood') || name.includes('msi') || name.includes('central');
      
      return name.includes(query) || comp.includes(query) || cat.includes(query) || addr.includes(query) || phone.includes(query) || email.includes(query);
    });

    if (filtered.length === 0) {
      vendorListEl.innerHTML = `
        <div style="padding:32px; text-align:center; background:#f8fafc; border:1px dashed #cbd5e1; border-radius:12px; margin-top:16px">
          <div style="font-size:24px; margin-bottom:8px">🔍</div>
          <div style="font-size:16px; font-weight:800; color:#0f172a">No suppliers found matching "${esc(query)}"</div>
          <div style="font-size:13px; color:#64748b; margin-top:4px">Try searching by category (cabinets, stone, flooring, hardware) or clear the filter.</div>
          <button class="btn secondary" style="margin-top:12px" onclick="document.getElementById('vendorFilter').value=''; renderVendors('');">Clear Search Filter</button>
        </div>
      `;
      return;
    }

    vendorListEl.innerHTML = `
      <div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(320px, 1fr)); gap:16px; margin-top:16px">
        ${filtered.map(v => {
          const catBadges = (v.category || []).map(c => `<span class="badge" style="background:#e0f2fe; color:#0369a1; font-size:11px; margin:0">${esc(c)}</span>`).join(' ');
          const hasPhone = Boolean(v.phone);
          const hasEmail = Boolean(v.email);
          const isTextable = (v.name || '').toLowerCase().includes('achilles');

          return `
            <div class="vendor-card card" style="display:flex; flex-direction:column; justify-content:space-between; border-radius:10px; border:1px solid #cbd5e1; padding:16px; background:#ffffff; box-shadow:0 1px 4px rgba(0,0,0,0.03); transition:transform 0.15s, box-shadow 0.15s">
              <div>
                <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:8px; gap:8px">
                  <h3 style="margin:0; font-size:16.5px; font-weight:800; color:#0f172a">${esc(v.name)}</h3>
                  ${isTextable ? '<span class="badge" style="background:#dc2626; color:#fff; font-size:10px; padding:2px 6px">Textable</span>' : ''}
                </div>
                
                <div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:10px">
                  ${catBadges || '<span class="badge" style="background:#f1f5f9; color:#475569; font-size:11px">Approved Supplier</span>'}
                </div>

                <div style="font-size:12.5px; color:#475569; display:flex; flex-direction:column; gap:4px; margin-bottom:14px">
                  ${hasPhone ? `<div>📞 <strong>Phone:</strong> <a href="tel:${esc(v.phone.replace(/[^0-9]/g,''))}" style="color:#0284c7; font-weight:700">${esc(v.phone)}</a></div>` : ''}
                  ${hasEmail ? `<div>✉️ <strong>Email:</strong> <a href="mailto:${esc(v.email)}" style="color:#0284c7">${esc(v.email)}</a></div>` : ''}
                  ${v.address ? `<div style="font-size:11.5px; color:#64748b">📍 ${esc(v.address)}</div>` : ''}
                </div>
              </div>

              <div style="display:flex; gap:8px; flex-wrap:wrap; padding-top:12px; border-top:1px solid #f1f5f9">
                <button class="btn" style="flex:1; background:#0284c7; color:#fff; font-weight:800; font-size:12px; padding:7px 10px; border:0; border-radius:6px; cursor:pointer" onclick="openVendorPriceListModal('${esc(v.name)}')">
                  📖 View Price List
                </button>
                <button class="btn secondary" style="font-size:12px; padding:7px 10px; border-radius:6px" onclick="openVendorQuoteComposer('${esc(v.name)}')">
                  ✉️ Quote
                </button>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }



