    const items = data.filter(item => {
      if (item.hcList === null) return false;
      return !query || item.sku.toLowerCase().includes(query) || item.name.toLowerCase().includes(query) || (item.desc || '').toLowerCase().includes(query) || (item.cat || '').toLowerCase().includes(query);
    });

