  if (qboApBalance) qboApBalance.innerHTML = isAdmin ? '$18,240.00' : '🔒 Restricted';
  if (qboBankBalance) qboBankBalance.innerHTML = isAdmin ? '$12,973.00' : '🔒 Restricted';
