function switchQboTab(tabId) {
  const adminOnlyTabs = ['accounts', 'reports', 'sync', 'payroll'];
  const isAdmin = isCurrentActiveUserAdmin();

  // Hide all qbo tab contents
  const contents = document.querySelectorAll('.qbo-tab-content');
  contents.forEach(el => el.style.display = 'none');

  // Deactivate all qbo nav buttons
  const buttons = document.querySelectorAll('.qbo-nav-tab');
  buttons.forEach(btn => btn.classList.remove('active'));

  const targetBtn = document.getElementById('qboTabBtn-' + tabId);
  if (targetBtn) targetBtn.classList.add('active');

  const targetContent = document.getElementById('qboTabContent-' + tabId);
  if (targetContent) {
    if (adminOnlyTabs.includes(tabId) && !isAdmin) {
      targetContent.style.display = 'block';
      targetContent.innerHTML = `
        <div style="background:#fff; border:2px solid #fecdd3; border-radius:12px; padding:36px 24px; text-align:center; max-width:620px; margin:30px auto; box-shadow:0 10px 25px rgba(0,0,0,0.06)">
          <div style="font-size:48px; margin-bottom:12px">🔒</div>
          <h3 style="margin:0 0 8px; font-size:20px; font-weight:800; color:#881337">Administrative Access Restricted</h3>
          <p style="margin:0 0 16px; font-size:14px; color:#9f1239; line-height:1.5">
            The <strong>${tabId.toUpperCase()}</strong> tab contains confidential executive accounting data. 
            Your current account <strong>${esc(currentActiveUser ? currentActiveUser.name : 'User')}</strong> is assigned the role <strong>${esc(currentActiveUser ? (currentActiveUser.qboRole || 'Sales QB User') : 'Sales QB User')}</strong>.
          </p>
          <div style="background:#fff1f2; border:1px solid #fda4af; border-radius:8px; padding:12px; font-size:12.5px; color:#475569; text-align:left; line-height:1.4; margin-bottom:20px">
            <strong>ℹ️ QuickBooks Permissions Notice:</strong> Only QBO Primary Admins & Company Admins (Gil Sirimarco, Edwin Portillo, Dave Siefers) have authorization to view Chart of Accounts, Company Financial Reports, Payroll & Team, and Direct QBO Batch Integrations.
          </div>
          <button onclick="openSettingsModal('permissions')" style="background:#9f1239; color:#fff; font-weight:800; border:0; padding:10px 20px; border-radius:8px; cursor:pointer; font-size:13px; box-shadow:0 4px 10px rgba(159,18,57,0.3)">
            🔑 Manage Users & Switch Active Account
          </button>
        </div>
      `;
    } else {
      targetContent.style.display = 'block';
      if (typeof renderAllQboTables === 'function') renderAllQboTables();
    }
  }
}




