const views=[...document.querySelectorAll('.view')];const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let viewHistory=['home'],historyIndex=0;
function goBack() {
  if (typeof historyIndex !== "undefined" && historyIndex > 0) {
    historyIndex--;
    const targetView = viewHistory[historyIndex];
    show(targetView, false);
  } else {
    show('home', false);
  }
}

function goForward() {
  if (typeof historyIndex !== "undefined" && typeof viewHistory !== "undefined" && historyIndex < viewHistory.length - 1) {
    historyIndex++;
    const targetView = viewHistory[historyIndex];
    show(targetView, false);
  }
}

function closeCurrentPage() {
  let closedModal = false;
  const modals = document.querySelectorAll('.modal-backdrop, .modal, [id$="Modal"], [id$="Overlay"]');
  modals.forEach(m => {
    if (m && (m.style.display === "block" || m.style.display === "flex" || m.classList.contains("active"))) {
      m.style.display = "none";
      m.classList.remove("active");
      closedModal = true;
    }
  });
  show("home");
}

