// 1. UNIVERSAL SEARCH EXECUTION ENGINE
function executeUniversalCSESearch(rawQuery) {
  const q = String(rawQuery || '').trim();
  if (!q) {
    showToast('⚠️ Please enter a search question, product name, SKU, price, or invoice number');
    return;
  }

  // Populate search inputs
  const qInput = document.getElementById('q');
  if (qInput) qInput.value = q;

  const mainInput = document.getElementById('googleMainInput');
  if (mainInput) mainInput.value = q;

  if (typeof closeQboSearchDropdown === 'function') closeQboSearchDropdown();
  openWorkspaceTab('search-engine', 'Google: ' + (q.length > 15 ? q.slice(0, 15) + '...' : q));
  executeGoogleSearchHub(q);
}

