function handleTerminalCustomerChange(val) {
  const select = document.getElementById('terminalCustomerSelect');
  if (!select) return;
  const opt = select.options[select.selectedIndex];
  if (!opt) return;

  const invRef = opt.getAttribute('data-inv') || '';
  const balance = parseFloat(opt.getAttribute('data-balance') || '0');

  const invInput = document.getElementById('terminalInvoiceRef');
  const baseInput = document.getElementById('terminalBaseAmount');

  if (invInput) invInput.value = invRef;
  if (baseInput && balance > 0) baseInput.value = balance.toFixed(2);

  updateTerminalSurchargeCalculation();
}

function updateTerminalSurchargeCalculation() {
  const baseInput = document.getElementById('terminalBaseAmount');
  const baseAmt = parseFloat(baseInput ? baseInput.value : '0') || 0;

  const isCC = document.querySelector('input[name="terminalFeeType"]:checked')?.value === 'cc_3pct';
  const feeRate = isCC ? 0.03 : 0.00;
  const feeAmt = baseAmt * feeRate;
  const totalAmt = baseAmt + feeAmt;

  const sumBase = document.getElementById('terminalSumBase');
  const sumFee = document.getElementById('terminalSumFee');
  const sumCredit = document.getElementById('terminalSumArCredit');
  const sumTotal = document.getElementById('terminalSumTotal');
  const submitText = document.getElementById('terminalSubmitBtnText');

  if (sumBase) sumBase.textContent = '$' + baseAmt.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (sumFee) sumFee.textContent = (isCC ? '+$' : '$') + feeAmt.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (sumCredit) sumCredit.textContent = '$' + baseAmt.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' Applied';
  if (sumTotal) sumTotal.textContent = '$' + totalAmt.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (submitText) submitText.textContent = `Process Payment: $${totalAmt.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function formatCardNumberInput(input) {
  let val = input.value.replace(/\D/g, '');
  let formatted = '';
  for (let i = 0; i < val.length; i++) {
    if (i > 0 && i % 4 === 0) formatted += ' ';
    formatted += val[i];
  }
  input.value = formatted;

  const badge = document.getElementById('terminalCardBrandBadge');
  if (!badge) return;

  if (val.startsWith('4')) {
    badge.innerHTML = '💳 <strong style="color:#0b57d0">Visa</strong>';
  } else if (val.startsWith('5')) {
    badge.innerHTML = '💳 <strong style="color:#ea580c">MasterCard</strong>';
  } else if (val.startsWith('34') || val.startsWith('37')) {
    badge.innerHTML = '💳 <strong style="color:#0284c7">American Express</strong>';
  } else if (val.startsWith('6')) {
    badge.innerHTML = '💳 <strong style="color:#eab308">Discover</strong>';
  } else {
    badge.innerHTML = '💳 Visa / MC / Amex / Disc';
  }
}

function formatCardExpInput(input) {
  let val = input.value.replace(/\D/g, '');
  if (val.length >= 3) {
    input.value = val.slice(0, 2) + '/' + val.slice(2, 4);
  } else {
    input.value = val;
  }
}

function processTerminalCharge(event) {
  event.preventDefault();

  const customerSelect = document.getElementById('terminalCustomerSelect');
  const customer = customerSelect ? customerSelect.value : 'Customer Sale';
  const baseAmt = parseFloat(document.getElementById('terminalBaseAmount')?.value || '0') || 0;
  const isCC = document.querySelector('input[name="terminalFeeType"]:checked')?.value === 'cc_3pct';
  const feeAmt = isCC ? baseAmt * 0.03 : 0.00;
  const totalAmt = baseAmt + feeAmt;
  const cardNum = document.getElementById('terminalCardNumber')?.value.replace(/\s/g, '') || '';
  const last4 = cardNum.slice(-4) || '1234';
  const cardholder = document.getElementById('terminalCardholder')?.value || 'Cardholder';
  const email = document.getElementById('terminalReceiptEmail')?.value || '';

  const authId = 'AUTH-' + Math.floor(10000 + Math.random() * 90000);
  const brandBadge = document.getElementById('terminalCardBrandBadge')?.textContent?.replace('💳', '').trim() || 'Credit Card';

  const newTx = {
    id: authId,
    customer: customer,
    baseAmt: baseAmt,
    feeAmt: feeAmt,
    totalAmt: totalAmt,
    cardBrand: isCC ? brandBadge : 'ACH Wire',
    cardLast4: last4,
    date: new Date().toISOString().replace('T', ' ').slice(0, 16),
    status: 'Approved & Settled'
  };

  terminalTransactions.unshift(newTx);
  renderTerminalTransactionsTable();

  // Audit log entry
  if (typeof logSecurityEvent === 'function') {
    logSecurityEvent('PAYMENT_PROCESSED', `Processed $${totalAmt.toFixed(2)} for ${customer} (${authId})`);
  }

  showToast(`✅ Payment Approved! Auth: ${authId} — Charged: $${totalAmt.toFixed(2)}`);

  // Show printable receipt modal
  printTerminalReceipt(authId, cardholder, email);
}

