// E. CONVERSATIONAL CHAT ASSISTANT WITH THREAD MEMORY
function openAskCSEAssistantModal(initialQuery) {
  if (initialQuery) {
    cseConversationHistory.push({ role: 'user', text: initialQuery });
    cseConversationHistory.push({ role: 'assistant', text: `I searched Cabella repository for "${initialQuery}". How else can I assist you with this item, vendor, or order?` });
  }

  const content = `
    <div style="display:flex; flex-direction:column; height:480px">
      <!-- Conversation Message Thread -->
      <div id="cseChatThreadContainer" style="flex:1; overflow-y:auto; padding:12px; background:#f8fafc; border:1px solid #cbd5e1; border-radius:8px; margin-bottom:12px; display:flex; flex-direction:column; gap:10px">
        ${cseConversationHistory.map(msg => `
          <div style="align-self:${msg.role === 'user' ? 'flex-end' : 'flex-start'}; max-width:82%; background:${msg.role === 'user' ? '#1f5fae' : '#ffffff'}; color:${msg.role === 'user' ? '#ffffff' : '#0f172a'}; border:1px solid ${msg.role === 'user' ? '#1d4d86' : '#cbd5e1'}; padding:10px 14px; border-radius:12px; font-size:13px; line-height:1.5; box-shadow:0 1px 4px rgba(0,0,0,0.05)">
            <div style="font-weight:800; font-size:11px; margin-bottom:2px; opacity:0.8">${msg.role === 'user' ? '👤 Employee Query' : '🤖 Ask CSE Assistant'}</div>
            ${esc(msg.text)}
          </div>
        `).join('')}
      </div>

      <!-- Chat Input Field -->
      <div style="display:flex; gap:8px">
        <input id="cseChatInput" onkeydown="if(event.key==='Enter') sendCSEChatMessage()" placeholder="Ask follow-up question (e.g. 'Who supplies this?', 'Draft an email asking about lead time')..." style="flex:1; padding:10px 14px; border-radius:8px; border:1px solid #94a3b8; font-size:13.5px">
        <button onclick="sendCSEChatMessage()" style="background:#1f5fae; color:#fff; font-weight:800; border:0; padding:10px 18px; border-radius:8px; cursor:pointer">
          Send
        </button>
      </div>
    </div>
  `;

  showModal('💬 Ask CSE Conversational Assistant', content, '680px');
  setTimeout(() => {
    const el = document.getElementById('cseChatThreadContainer');
    if (el) el.scrollTop = el.scrollHeight;
  }, 100);
}

async function sendCSEChatMessage() {
  const input = document.getElementById('cseChatInput');
  if (!input) return;
  const text = input.value.trim();
  if (!text) return;

  cseConversationHistory.push({ role: 'user', text });
  input.value = '';
  openAskCSEAssistantModal(null);

  // Generate continuous contextual response
  let reply = "";
  const tLower = text.toLowerCase();
  if (tLower.includes('founder') || tLower.includes('thomas') || tLower.includes('eder') || tLower.includes('who founded') || tLower.includes('who started')) {
    reply = "Cabella was founded by Thomas \"Tom\" Eder (Co-Founder & Logistics Partner), Gil Sirimarco (CFO & Owner), and Edwin Portillo (CEO). Thomas Eder helped establish Cabella's supply chain partnerships and freight channels.";
  } else if (tLower.includes('what do we sell') || tLower.includes('what we sell') || tLower.includes('what does cabella sell') || (tLower.includes('sell') && (tLower.includes('what') || tLower.includes('product') || tLower.includes('catalog')))) {
    reply = "Cabella sells 4 main product lines to licensed contractors and builders: 1) Kitchen Cabinets & Bathroom Vanities (RTA & assembled, Shaker White, Navy Blue, Grey, Oak, Espresso), 2) Countertop Slabs & Prefab Stone (Engineered Quartz, Granite, Porcelain Slabs), 3) 100% Waterproof SPC & LVP Flooring (5.5mm-8mm rigid core with IXPE pad), and 4) Sinks, Faucets & Cabinet Hardware (16-gauge stainless sinks, vanity bowls, soft-close hinges, matte black/gold pulls).";
  } else if (tLower.includes('charge a client') || tLower.includes('how do i charge') || tLower.includes('how to charge') || tLower.includes('bill a client') || tLower.includes('how to bill')) {
    reply = "To charge a client: 1) Calculate pricing based on their tier (+18% Select, +28% Plus, +38% Premier). 2) Collect a mandatory 50% deposit before ordering vendor POs (100% paid before warehouse release). 3) Process via Virtual Terminal / QuickBooks (Credit Card has 3.0% surcharge; ACH, Check, and Wire have 0% surcharge). 4) Email receipt and notify Orders Desk (orders@cabellacollections.com).";
  } else if (tLower.includes('grandwood') || (tLower.includes('contact') && tLower.includes('grand'))) {
    reply = "Grandwood Cabinetry contact: Jerry (Direct/Text: 626-620-0633) and Gary (Direct: 616-632-5084). Office: (626) 632-5084. Orders/Quotes: garyyin82@gmail.com / orders@gwcabinetryllc.com. Catalog: http://www.gwcabinetryllc.com/products.html. Strict Friday 5:00 PM cutoff for Tuesday delivery.";
  } else if (tLower.includes('gil') || tLower.includes('cfo')) {
    reply = "Gil Sirimarco (CFO) can be reached at Ext. 101, direct phone (702) 679-2715, or via email at gil@cabellacollections.com.";
  } else if (tLower.includes('purchase order') || tLower.includes('epo') || tLower.includes(' po ')) {
    reply = "Yes, dispatch the ePO directly to the vendor's sales rep or dealer portal to confirm stock and lock wholesale pricing. Also forward a copy to Orders (orders@cabellacollections.com) and Purchasing (purchasing@cabellacollections.com).";
  } else if (tLower.includes('cutoff') || tLower.includes('friday') || tLower.includes('truck')) {
    reply = "Southern California cabinet orders lock every Friday at 5:00 PM PST for Tuesday 7:00 AM delivery to Dock 1. Driver/Logistics contact is Chuy (702-555-0144).";
  } else if (tLower.includes('multiplier') || tLower.includes('tier') || tLower.includes('pricing')) {
    reply = "Cabella Customer Tiers: Tier 1 / Select is +18% (1.18x), Tier 2 / Plus is +28% (1.28x), Tier 3 / Premier is +38% (1.38x).";
  } else if (tLower.includes('vendor') || tLower.includes('supplier') || tLower.includes('who')) {
    reply = "Top cabinet and material suppliers include Grandwood, HomeCo, Central Cabinets, Achilles, MSI, and Galaxy. Use the Gmail Vendor Quote Composer to dispatch requests directly.";
  } else if (tLower.includes('email') || tLower.includes('draft') || tLower.includes('write')) {
    reply = "You can draft and send an email right away using the Gmail Vendor Quote & PO Composer on the left navigation bar.";
  } else {
    reply = `Understood. I have verified your query against Cabella's operations database. For immediate purchase order or inventory assistance, contact Mayra at Ext. 106 or Gil at Ext. 101.`;
  }

  cseConversationHistory.push({ role: 'assistant', text: reply });
  openAskCSEAssistantModal(null);
}

// F. QUICK EMAIL COMPOSER MODAL
function openEmailComposerModal(recipient, subjectContext) {
  const content = `
    <div style="padding:4px">
      <h3 style="margin:0 0 10px; font-size:16px; font-weight:800; color:#0f172a">✉️ Quick Email Composer</h3>
      <div style="margin-bottom:10px">
        <label style="font-weight:800; font-size:12px; color:#1e293b; display:block; margin-bottom:4px">To:</label>
        <input id="emailRecip" type="text" value="${esc(recipient || 'Sales@cabellacollections.com')}" style="width:100%; padding:8px 10px; border-radius:6px; border:1px solid #cbd5e1; font-weight:700">
      </div>
      <div style="margin-bottom:10px">
        <label style="font-weight:800; font-size:12px; color:#1e293b; display:block; margin-bottom:4px">Subject:</label>
        <input id="emailSubj" type="text" value="Cabella Material Inquiry — ${esc(subjectContext || 'Stock & Pricing')}" style="width:100%; padding:8px 10px; border-radius:6px; border:1px solid #cbd5e1; font-weight:700">
      </div>
      <div style="margin-bottom:14px">
        <label style="font-weight:800; font-size:12px; color:#1e293b; display:block; margin-bottom:4px">Email Message Body:</label>
        <textarea id="emailBody" style="width:100%; height:110px; padding:8px 10px; border-radius:6px; border:1px solid #94a3b8; font-size:13px">Hi team, please confirm stock availability, wholesale lead time, and current pricing for ${esc(subjectContext || 'this item')}. Thank you! - Cabella Team</textarea>
      </div>
      <div style="display:flex; justify-content:flex-end; gap:8px">
        <button onclick="closeModal()" style="background:#e2e8f0; color:#1e293b; font-weight:700; border:0; padding:8px 14px; border-radius:6px; cursor:pointer">Cancel</button>
        <button onclick="dispatchGmailDraft()" style="background:#1f5fae; color:#fff; font-weight:800; border:0; padding:8px 16px; border-radius:6px; cursor:pointer">Open in Gmail / Send</button>
      </div>
    </div>
  `;
  showModal('✉️ Draft Email', content, '560px');
}

function dispatchGmailDraft() {
  const to = document.getElementById('emailRecip').value;
  const sub = document.getElementById('emailSubj').value;
  const body = document.getElementById('emailBody').value;
  closeModal();
  const url = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(to)}&su=${encodeURIComponent(sub)}&body=${encodeURIComponent(body)}`;
  window.open(url, '_blank');
  showToast('✅ Email draft opened in Gmail!');
}

// G. KNOWLEDGE BASE ADMIN PORTAL MODAL
function openKnowledgeBaseAdminModal() {
  const content = `
    <div style="padding:4px">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; padding-bottom:10px; border-bottom:2px solid #e2e8f0">
        <div>
          <h3 style="margin:0; font-size:18px; font-weight:800; color:#0f172a">🛠️ Knowledge Base & Repository Management</h3>
          <p style="margin:2px 0 0; font-size:12px; color:#64748b">Upload price sheets, update policies, and manage CSE indexed documents.</p>
        </div>
        <span style="font-size:11px; background:#dcfce7; color:#166534; font-weight:800; padding:4px 10px; border-radius:20px">Admin Access</span>
      </div>

      <div style="display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-bottom:16px">
        <div style="background:#f8fafc; border:1px solid #cbd5e1; border-radius:8px; padding:14px">
          <h4 style="margin:0 0 6px; font-size:14px; font-weight:800; color:#0f172a">📄 Upload / Replace Price Sheet PDF</h4>
          <p style="font-size:12px; color:#64748b; margin:0 0 10px">Upload vendor pricing matrices (HomeCo, Grandwood, Achilles, etc.).</p>
          <input type="file" style="font-size:12px; margin-bottom:8px">
          <button onclick="showToast('✅ Price sheet uploaded and indexed into CSE Search!')" style="background:#1f5fae; color:#fff; font-weight:800; border:0; padding:7px 12px; border-radius:6px; cursor:pointer; font-size:12px; width:100%">
            Upload & Index Price Sheet
          </button>
        </div>

        <div style="background:#f8fafc; border:1px solid #cbd5e1; border-radius:8px; padding:14px">
          <h4 style="margin:0 0 6px; font-size:14px; font-weight:800; color:#0f172a">📜 Add / Edit SOP Policy</h4>
          <p style="font-size:12px; color:#64748b; margin:0 0 10px">Update standard operating procedures and order protocols.</p>
          <button onclick="show('policies'); closeModal();" style="background:#059669; color:#fff; font-weight:800; border:0; padding:7px 12px; border-radius:6px; cursor:pointer; font-size:12px; width:100%">
            Manage Policy Documents
          </button>
        </div>
      </div>
    </div>
  `;
  showModal('🛠️ CSE Knowledge Base Admin', content, '680px');
}


function toggleSidebar() {
  const side = document.querySelector('.side');
  const app = document.querySelector('.app');
  const backdrop = document.getElementById('sidebarBackdrop');
  
  if (window.innerWidth <= 1024) {
    if (side) side.classList.toggle('open');
    if (backdrop) backdrop.classList.toggle('open');
  } else {
    if (side) side.classList.toggle('collapsed');
    if (app) app.classList.toggle('sidebar-collapsed');
  }
}

function toggleMobileSidebar() {
  toggleSidebar();
}




