function submitClientElectronicOk(estimateId) {
  const signerName = document.getElementById('clientEsignName')?.value?.trim();
  const fulfillDate = document.getElementById('clientEsignFulfillmentDate')?.value;
  const termsChecked = document.getElementById('clientEsignTerms')?.checked;

  if (!signerName) return showToast('Please enter the client legal signer name.');
  if (!fulfillDate) return showToast('Please select the requested fulfillment date.');
  if (!termsChecked) return showToast('Please accept the authorization terms checkbox.');

  const store = getQboStore();
  const estIdx = (store.estimates || []).findIndex(e => e.id === estimateId);
  if (estIdx === -1) return showToast('Estimate not found');

  const est = store.estimates[estIdx];
  const nowStr = new Date().toISOString().replace('T', ' ').substring(0, 19);

  // 1. Update Estimate
  est.status = 'Client Approved (E-Signed)';
  est.eSignDate = nowStr;
  est.eSignerName = signerName;
  est.requestedFulfillmentDate = fulfillDate;

  // 2. Automatically generate the corresponding Invoice with Due on Receipt (DUR)
  const newInvoiceId = (est.id.replace('EST-', '').replace('20', '84') || '8455');
  est.invoiceId = newInvoiceId;

  const totalAmount = Number(est.total);

  const invoiceRecord = {
    id: newInvoiceId,
    customer: est.customer,
    jobsite: est.jobsite,
    shipTo: est.shipTo || (est.customer + '\n' + est.jobsite),
    date: new Date().toISOString().split('T')[0],
    dueDate: new Date().toISOString().split('T')[0],
    terms: 'Due on receipt',
    salesRep: est.salesRep || 'Jerry Maza (PM)',
    poNumber: est.poNumber || ('EST-' + est.id),
    items: est.items || [],
    subtotal: est.subtotal,
    taxRate: est.taxRate || 0.08375,
    taxAmount: est.taxAmount || 0,
    shipping: est.shipping || 0,
    total: est.total,
    deposit: 0.00,
    balanceDue: totalAmount,
    status: 'Unpaid (Due on Receipt)',
    clientFulfillmentDate: fulfillDate,
    eSignVerification: `E-Signed by ${signerName} on ${nowStr}`,
    paymentInstructions: 'Zelle: Zelle@CabellaCollections.com | Check: Cabella Cabinets Stone & Flooring',
    customerNote: `Thank you for approving your project! Terms: Due on Receipt (DUR). Requested fulfillment date: ${fulfillDate}.`,
    internalNotes: `Auto-generated from approved Estimate #${est.id}. Client requested fulfillment: ${fulfillDate}. PM can now create internal PO for Purchaser.`
  };

  const invIdx = store.invoices.findIndex(inv => inv.id === newInvoiceId);
  if (invIdx !== -1) store.invoices[invIdx] = invoiceRecord;
  else store.invoices.unshift(invoiceRecord);

  // 3. Automatically link or create the Jobsite Project
  let proj = (store.projects || []).find(p => p.estimateId === estimateId || p.id === ('PROJ-' + (est.id.replace('EST-', ''))));
  if (!proj) {
    const projId = 'PROJ-' + (est.id.replace('EST-', '') || Math.floor(Math.random() * 900 + 8400));
    proj = {
      id: projId,
      name: est.jobsite ? est.jobsite.split('/')[0].trim() : (est.customer + ' Project'),
      client: est.customer,
      address: est.shipTo || est.jobsite || 'Las Vegas, NV',
      pm: est.salesRep || 'Carlos Cruz (PM)',
      contractValue: totalAmount,
      invoiced: totalAmount,
      expenses: 0.00,
      status: 'Active',
      estimateId: est.id,
      invoiceId: newInvoiceId
    };
    store.projects.unshift(proj);
    est.projectId = projId;
  } else {
    proj.invoiced = totalAmount;
    proj.invoiceId = newInvoiceId;
    est.projectId = proj.id;
  }

  saveQboStore(store);
  closeModal();
  renderAllQboTables();
  showToast(`✅ Estimate #${estimateId} E-Signed! Invoice #${newInvoiceId} & Jobsite Project created.`);
}

function convertEstimateToInvoice(estimateId) {
  openClientElectronicOkModal(estimateId);
}

// Turn an Estimate into a Jobsite Project
function turnEstimateIntoProject(estimateId) {
  const store = getQboStore();
  const est = (store.estimates || []).find(e => e.id === estimateId);
  if (!est) {
    showToast('❌ Estimate not found.');
    return;
  }

  // Check if project already exists for this estimate
  let existingProj = (store.projects || []).find(p => p.estimateId === estimateId || (est.jobsite && p.name && (p.name.toLowerCase() === est.jobsite.toLowerCase() || est.jobsite.toLowerCase().includes(p.name.toLowerCase()))));
  
  if (existingProj) {
    showToast(`ℹ️ Jobsite Project already active: ${existingProj.name} (${existingProj.id})`);
    navigateToQbo('projects');
    openQboTransactionModal('Project', existingProj.id);
    return;
  }

  const cleanNum = est.id.replace('EST-', '').trim() || String(Math.floor(Math.random() * 900 + 8415));
  const newProjId = 'PROJ-' + cleanNum;
  const projName = est.jobsite ? est.jobsite.split('/')[0].trim() : (est.customer ? (est.customer + ' Jobsite') : 'New Jobsite Project');
  const projAddress = est.shipTo ? est.shipTo.replace(est.customer, '').trim() : (est.jobsite || '4625 West Nevso Dr Suite 6 Las vegas Nevada 89103');
  
  const newProject = {
    id: newProjId,
    name: projName,
    client: est.customer || 'Client',
    address: projAddress || est.jobsite || '4625 West Nevso Dr Suite 6 Las vegas Nevada 89103',
    pm: est.salesRep || 'Carlos Cruz (PM)',
    contractValue: Number(est.total) || 0.00,
    invoiced: est.invoiceId ? Number(est.total) : 0.00,
    expenses: 0.00,
    status: 'Active',
    estimateId: est.id,
    invoiceId: est.invoiceId || null
  };

  est.projectId = newProjId;
  store.projects.unshift(newProject);
  saveQboStore(store);

  showToast(`🏗️ Created Jobsite Project "${newProject.name}" from Estimate #${est.id}!`);
  navigateToQbo('projects');
  renderAllQboTables();
  
  // Open the project modal for immediate viewing / editing
  setTimeout(() => {
    openQboTransactionModal('Project', newProjId);
  }, 200);
}

function convertEstimateToProject(estimateId) {
  turnEstimateIntoProject(estimateId);
}

