    { name: 'Jerry Maza', role: 'Head Project Manager', email: 'jerry@cabellacollections.com', phone: '(702) 679-2239', extension: '104', system: 'RingCentral' },
    { name: 'Margie Caro', role: 'Project Manager & Sales', email: 'pm@cabellacollections.com', phone: '(725) 255-2835', extension: '107', system: 'RingCentral' },
    { name: 'Chuy', role: 'Warehouse Manager', email: 'inbox@cabellacollections.com', phone: 'Main line: (702) 879-2549', extension: '', system: 'Company' }
