function exportDirectoryCSV() {
  const people = (typeof BASE_DATA !== 'undefined' && BASE_DATA.people) ? BASE_DATA.people : [];
  let csv = 'Name,Role,Extension,Phone,Email,System\n';
  people.forEach(p => {
    csv += `"${p.name}","${p.role}","${p.extension || 'Main'}","${p.phone}","${p.email || ''}","${p.system || 'RingCentral'}"\n`;
  });
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'Cabella_Staff_Directory.csv';
  a.click();
  URL.revokeObjectURL(url);
}

