let activeWarehouseFilter = 'all';

function getWarehouseOrders() {
  try {
    const raw = localStorage.getItem('cabellaWarehouseOrders');
    if (raw) return JSON.parse(raw);
  } catch(e) {}
  localStorage.setItem('cabellaWarehouseOrders', JSON.stringify(DEFAULT_WAREHOUSE_ORDERS));
  return DEFAULT_WAREHOUSE_ORDERS;
}

function saveWarehouseOrders(orders) {
  localStorage.setItem('cabellaWarehouseOrders', JSON.stringify(orders));
  renderWarehouseFeed();
}

function filterWarehouseFeed(statusKey) {
  activeWarehouseFilter = statusKey;
  document.querySelectorAll('.wh-filter-card').forEach(card => {
    card.classList.remove('active');
    card.style.border = '1px solid #cbd5e1';
  });
  const activeCard = document.getElementById(`whFilterCard-${statusKey}`);
  if (activeCard) {
    activeCard.classList.add('active');
    activeCard.style.border = '2px solid #0284c7';
  }
  renderWarehouseFeed();
}


function renderWarehouseFeed() {
  const container = document.getElementById('warehouseLiveFeedContainer');
  if (!container) return;

  const orders = getWarehouseOrders();
  const search = (document.getElementById('whFeedSearchInput')?.value || '').toLowerCase().trim();

  let countAll = orders.length;
  let countAssembling = orders.filter(o => o.status === 'assembling').length;
  let countMissing = orders.filter(o => o.status === 'missing').length;
  let countReady = orders.filter(o => o.status === 'ready').length;
  let countCompleted = orders.filter(o => o.status === 'completed').length;

  if (document.getElementById('whStatCountAll')) document.getElementById('whStatCountAll').textContent = `${countAll} Active Orders`;
  if (document.getElementById('whStatCountAllModal')) document.getElementById('whStatCountAllModal').textContent = `${countAll} Active`;
  if (document.getElementById('whStatCountAssembling')) document.getElementById('whStatCountAssembling').textContent = `🟡 ${countAssembling} Assembling`;
  if (document.getElementById('whStatCountAssemblingModal')) document.getElementById('whStatCountAssemblingModal').textContent = `${countAssembling} Order${countAssembling === 1 ? '' : 's'}`;
  if (document.getElementById('whStatCountMissing')) document.getElementById('whStatCountMissing').textContent = `🟠 ${countMissing} Missing`;
  if (document.getElementById('whStatCountMissingModal')) document.getElementById('whStatCountMissingModal').textContent = `${countMissing} Order${countMissing === 1 ? '' : 's'}`;
  if (document.getElementById('whStatCountReady')) document.getElementById('whStatCountReady').textContent = `🟢 ${countReady} Ready in Bin`;
  if (document.getElementById('whStatCountReadyModal')) document.getElementById('whStatCountReadyModal').textContent = `${countReady} Order${countReady === 1 ? '' : 's'}`;
  if (document.getElementById('whStatCountCompleted')) document.getElementById('whStatCountCompleted').textContent = `🔵 ${countCompleted} Completed`;
  if (document.getElementById('whStatCountCompletedModal')) document.getElementById('whStatCountCompletedModal').textContent = `${countCompleted} Order${countCompleted === 1 ? '' : 's'}`;

  let filtered = orders;
  if (activeWarehouseFilter !== 'all') {
    filtered = filtered.filter(o => o.status === activeWarehouseFilter);
  }

  if (search) {
    filtered = filtered.filter(o => 
      (o.projectName || '').toLowerCase().includes(search) ||
      (o.customer || '').toLowerCase().includes(search) ||
      (o.poNumber || '').toLowerCase().includes(search) ||
      (o.invoiceNumber || '').toLowerCase().includes(search) ||
      (o.binNumber || '').toLowerCase().includes(search) ||
      (o.vendorName || '').toLowerCase().includes(search)
    );
  }

  if (filtered.length === 0) {
    container.innerHTML = `
      <div style="text-align: center; padding: 24px; background: #f8fafc; border: 1px dashed #cbd5e1; border-radius: 10px; color: #64748b">
        📦 No warehouse orders match the selected filter. Click "+ Add New Order" or clear search.
      </div>
    `;
    return;
  }

  const lifecycleSteps = [
    "✍️ Signed Est.",
    "📄 Invoice Billed",
    "💰 Client Paid",
    "🏭 Vendor PO",
    "🚚 Shipped",
    "📦 Assembled & Bin",
    "🛍️ Pickup / Delivered"
  ];

  const photoStore = (typeof getPhotoProofStore === 'function') ? getPhotoProofStore() : {};

  container.innerHTML = filtered.map(order => {
    let badgeBg = "#fefce8", badgeColor = "#854d0e", badgeBorder = "#fef08a", statusIcon = "🟡";
    if (order.status === "missing") {
      badgeBg = "#fff7ed"; badgeColor = "#c2410c"; badgeBorder = "#ffedd5"; statusIcon = "🟠";
    } else if (order.status === "ready") {
      badgeBg = "#f0fdf4"; badgeColor = "#166534"; badgeBorder = "#bbf7d0"; statusIcon = "🟢";
    } else if (order.status === "completed") {
      badgeBg = "#f0f9ff"; badgeColor = "#0369a1"; badgeBorder = "#bae6fd"; statusIcon = "🔵";
    }

    const currentStage = order.lifecycleStage || (order.status === 'completed' ? 7 : 6);

    const stepBarHtml = lifecycleSteps.map((stepName, idx) => {
      const stepNum = idx + 1;
      const isDone = stepNum <= currentStage;
      const isCurrent = stepNum === currentStage;
      let stepBg = isDone ? "#0284c7" : "#e2e8f0";
      let stepTxt = isDone ? "#ffffff" : "#64748b";
      let borderStyle = isCurrent ? "2px solid #0f172a" : "none";

      return `
        <div style="flex: 1; text-align: center">
          <div style="background: ${stepBg}; color: ${stepTxt}; border: ${borderStyle}; font-weight: 800; font-size: 10px; padding: 4px 2px; border-radius: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis" title="Step ${stepNum}: ${stepName}">
            ${stepNum}. ${stepName}
          </div>
        </div>
      `;
    }).join('');

    const notesList = order.notes || [];
    const notesHtml = notesList.map(n => `
      <div style="background: #ffffff; border: 1px solid #e2e8f0; padding: 6px 10px; border-radius: 6px; font-size: 12px">
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 2px">
          <strong style="color: #0f172a; font-size: 11.5px">${n.author || 'Cabella Staff'}</strong>
          <span style="font-size: 10px; color: #94a3b8">${n.timestamp || ''}</span>
        </div>
        <div style="color: #334155; line-height: 1.35">${n.text}</div>
      </div>
    `).join('');

    // Check photos and signature for this order
    const proof = photoStore[order.id] || photoStore[order.poNumber] || { driverPickupPhotos: [], warehouseDropoffPhotos: [], warehousePickingPhotos: [], truckLoadedPhotos: [], clientPickupRelease: null };
    const totalPhotos = (proof.driverPickupPhotos?.length || 0) + (proof.warehouseDropoffPhotos?.length || 0) + (proof.warehousePickingPhotos?.length || 0) + (proof.truckLoadedPhotos?.length || 0);
    const hasSignature = !!proof.clientPickupRelease;

    return `
      <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 12px; padding: 16px; box-shadow: 0 2px 6px rgba(0,0,0,0.03)">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 10px; margin-bottom: 10px">
          <div>
            <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap">
              <span style="font-size: 16px; font-weight: 900; color: #0f172a">${order.projectName}</span>
              <span style="font-size: 11px; background: #e2e8f0; color: #334155; font-weight: 800; padding: 2px 8px; border-radius: 4px">${order.vendorName || 'Supplier Order'}</span>
              ${hasSignature ? `<span style="background: #dcfce7; color: #166534; font-weight: 800; font-size: 11px; padding: 2px 8px; border-radius: 12px; border: 1px solid #bbf7d0">✍️ Client Signed & Loaded</span>` : ''}
            </div>
            <div style="display: flex; gap: 12px; font-size: 12px; color: #475569; margin-top: 4px; flex-wrap: wrap">
              <span>👤 <strong>Customer:</strong> ${order.customer}</span>
              <span>📄 <strong>Invoice #:</strong> <strong style="color:#0284c7">${order.invoiceNumber || 'N/A'}</strong></span>
              <span>🏭 <strong>PO #:</strong> <strong style="color:#0f766e">${order.poNumber || 'N/A'}</strong></span>
            </div>
          </div>
          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap">
            <span style="background: ${badgeBg}; color: ${badgeColor}; border: 1px solid ${badgeBorder}; font-weight: 800; font-size: 12px; padding: 4px 10px; border-radius: 20px; display: flex; align-items: center; gap: 4px">
              ${statusIcon} ${order.statusLabel || 'Processing'}
            </span>
            <span style="background: #0f172a; color: #ffffff; font-weight: 800; font-size: 12px; padding: 4px 10px; border-radius: 6px">
              📍 ${order.binNumber || 'Unassigned Bin'}
            </span>
            <button class="btn" onclick="openUpdateOrderStatusModal('${order.id}')" style="background: #0284c7; color: #fff; font-size: 11.5px; font-weight: 800; padding: 5px 12px; border-radius: 6px; border: 0; cursor: pointer">
              ⚡ Update Status
            </button>
          </div>
        </div>

        <div style="font-size: 12px; color: #334155; background: #f8fafc; border: 1px solid #e2e8f0; padding: 8px 12px; border-radius: 6px; margin-bottom: 10px">
          📦 <strong>Package Details:</strong> ${order.itemsSummary || 'Standard cabinet/stone materials package'}
        </div>

        ${order.missingItems ? `
          <div style="background: #fff7ed; border: 1px solid #ffedd5; border-left: 4px solid #ea580c; padding: 8px 12px; border-radius: 6px; margin-bottom: 10px; font-size: 12px; color: #9a3412">
            <strong>⚠️ MISSING PARTS / WAITING VENDOR REPLACEMENT:</strong> ${order.missingItems}
          </div>
        ` : ''}

        <!-- 📸 PHOTO INSPECTION & SIGNATURE PROOF ACTION STRIP -->
        <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; background: #f0f9ff; border: 1px solid #bae6fd; border-radius: 8px; padding: 8px 12px; margin-bottom: 10px">
          <div style="display: flex; align-items: center; gap: 8px; font-size: 12px">
            <span style="font-weight: 800; color: #0369a1">📸 Photos & Proof:</span>
            <span style="font-size: 11.5px; color: #0f172a; font-weight: 700">${totalPhotos} Photo${totalPhotos === 1 ? '' : 's'} on File</span>
            ${hasSignature ? `<span style="color: #166534; font-weight: 800">· ✍️ Signed by ${esc(proof.clientPickupRelease.clientName)}</span>` : ''}
          </div>

          <div style="display: flex; align-items: center; gap: 6px">
            <button onclick="openPoPhotoModal('${order.id}', '${esc(order.projectName)}', 'warehousePickingPhotos')" style="background: #ffffff; color: #0284c7; border: 1px solid #0284c7; font-size: 11.5px; font-weight: 800; padding: 4px 10px; border-radius: 6px; cursor: pointer; display: flex; align-items: center; gap: 4px">
              <span>📷</span> <span>Add / View Photos (${totalPhotos})</span>
            </button>
            <button onclick="openClientSignatureModal('${order.id}')" style="background: ${hasSignature ? '#166534' : '#0f172a'}; color: #ffffff; border: 0; font-size: 11.5px; font-weight: 800; padding: 4px 12px; border-radius: 6px; cursor: pointer; display: flex; align-items: center; gap: 4px">
              <span>✍️</span> <span>${hasSignature ? 'View / Re-sign Release' : 'Load Truck & Get Signature'}</span>
            </button>
            ${hasSignature ? `
              <button onclick="openPodReceiptModal('${order.id}')" style="background: #f0fdf4; color: #166534; border: 1px solid #bbf7d0; font-size: 11.5px; font-weight: 800; padding: 4px 10px; border-radius: 6px; cursor: pointer">
                📄 View Signed POD
              </button>
            ` : ''}
          </div>
        </div>

        <div style="margin-bottom: 10px">
          <div style="font-size: 10.5px; font-weight: 800; color: #64748b; margin-bottom: 4px; text-transform: uppercase">QBO PROJECT LIFECYCLE STAGE (STEP ${currentStage} OF 7):</div>
          <div style="display: flex; gap: 4px">
            ${stepBarHtml}
          </div>
        </div>

        <div style="background: #f1f5f9; border: 1px solid #e2e8f0; border-radius: 8px; padding: 10px">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px">
            <span style="font-size: 11px; font-weight: 800; color: #475569; text-transform: uppercase">💬 Orders Desk & Warehouse Communication Stream</span>
            <span style="font-size: 10.5px; color: #64748b">Last updated: ${order.updatedAt || 'Recently'} by ${order.updatedBy || 'Staff'}</span>
          </div>
          
          <div style="display: flex; flex-direction: column; gap: 6px; max-height: 120px; overflow-y: auto; margin-bottom: 8px">
            ${notesHtml.length > 0 ? notesHtml : '<div style="font-size: 11.5px; color: #94a3b8">No messages posted yet. Post a note below.</div>'}
          </div>

          <div style="display: flex; gap: 6px">
            <input id="whNoteInput-${order.id}" placeholder="Type note for sales & orders desk (e.g. 'Chuy: Received boxes, assembling now')..." style="flex: 1; padding: 6px 10px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12px" onkeydown="if(event.key==='Enter') postWarehouseOrderNote('${order.id}', 'whNoteInput-${order.id}')">
            <button onclick="postWarehouseOrderNote('${order.id}', 'whNoteInput-${order.id}')" style="background: #0f172a; color: #fff; font-weight: 800; font-size: 11.5px; padding: 6px 12px; border-radius: 6px; border: 0; cursor: pointer">
              Send Note
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function openUpdateOrderStatusModal(orderId = null) {
  const modal = document.getElementById('updateOrderStatusModal');
  if (!modal) return;

  const orders = getWarehouseOrders();
  const selectOrder = document.getElementById('whModalOrderSelect');
  if (selectOrder) {
    selectOrder.innerHTML = orders.map(o => `
      <option value="${o.id}">${o.projectName} — ${o.invoiceNumber || o.poNumber}</option>
    `).join('');
    if (orderId) selectOrder.value = orderId;
  }

  loadWarehouseModalOrderFields();
  modal.style.display = 'flex';
}

function loadWarehouseModalOrderFields() {
  const orderId = document.getElementById('whModalOrderSelect')?.value;
  if (!orderId) return;

  const orders = getWarehouseOrders();
  const order = orders.find(o => o.id === orderId);
  if (!order) return;

  if (document.getElementById('whModalStatusSelect')) document.getElementById('whModalStatusSelect').value = order.status || 'assembling';
  if (document.getElementById('whModalBinInput')) document.getElementById('whModalBinInput').value = order.binNumber || '';
  if (document.getElementById('whModalMissingInput')) document.getElementById('whModalMissingInput').value = order.missingItems || '';
  if (document.getElementById('whModalStageSelect')) document.getElementById('whModalStageSelect').value = order.lifecycleStage || 6;
  if (document.getElementById('whModalNoteInput')) document.getElementById('whModalNoteInput').value = '';
}

function closeUpdateOrderStatusModal() {
  const modal = document.getElementById('updateOrderStatusModal');
  if (modal) modal.style.display = 'none';
}

function saveOrderStatusUpdate() {
  const orderId = document.getElementById('whModalOrderSelect')?.value;
  if (!orderId) return;

  const orders = getWarehouseOrders();
  const order = orders.find(o => o.id === orderId);
  if (!order) return;

  const newStatus = document.getElementById('whModalStatusSelect').value;
  const newBin = document.getElementById('whModalBinInput').value.trim();
  const newMissing = document.getElementById('whModalMissingInput').value.trim();
  const newStage = parseInt(document.getElementById('whModalStageSelect').value);
  const newNoteText = document.getElementById('whModalNoteInput').value.trim();

  let statusLabel = "Received & Assembling";
  if (newStatus === "missing") statusLabel = "Assembled — Missing Items";
  if (newStatus === "ready") statusLabel = "Assembled & Ready in Bin";
  if (newStatus === "completed") statusLabel = "Picked Up / Complete";

  order.status = newStatus;
  order.statusLabel = statusLabel;
  order.binNumber = newBin || 'Unassigned Bin';
  order.missingItems = newMissing;
  order.lifecycleStage = newStage;

  const currentUser = (typeof currentActiveUser !== 'undefined' && currentActiveUser.name) ? currentActiveUser.name : 'Cabella Staff';
  order.updatedBy = currentUser;
  const timeNow = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ', Today';
  order.updatedAt = timeNow;

  if (newNoteText) {
    if (!order.notes) order.notes = [];
    order.notes.push({
      author: currentUser,
      text: newNoteText,
      timestamp: timeNow
    });
  }

  saveWarehouseOrders(orders);
  closeUpdateOrderStatusModal();
  if (typeof showToast === 'function') showToast(`✅ Status updated for ${order.projectName}!`);
}

function openNewWarehouseOrderModal() {
  const modal = document.getElementById('newWarehouseOrderModal');
  if (modal) modal.style.display = 'flex';
}

function closeNewWarehouseOrderModal() {
  const modal = document.getElementById('newWarehouseOrderModal');
  if (modal) modal.style.display = 'none';
}

function saveNewWarehouseOrder() {
  const projectName = document.getElementById('newWhProjectName')?.value.trim();
  const customer = document.getElementById('newWhCustomer')?.value.trim();
  const poNumber = document.getElementById('newWhPoNumber')?.value.trim();
  const invoiceNumber = document.getElementById('newWhInvoiceNumber')?.value.trim();
  const vendorName = document.getElementById('newWhVendorName')?.value.trim();
  const itemsSummary = document.getElementById('newWhItemsSummary')?.value.trim();
  const status = document.getElementById('newWhStatus')?.value || 'assembling';
  const binNumber = document.getElementById('newWhBinNumber')?.value.trim() || 'Staging Area A';

  if (!projectName || !customer) {
    alert("Please enter a Project Name and Customer Name.");
    return;
  }

  let statusLabel = "Received & Assembling";
  if (status === "missing") statusLabel = "Assembled — Missing Items";
  if (status === "ready") statusLabel = "Assembled & Ready in Bin";
  if (status === "completed") statusLabel = "Picked Up / Complete";

  const randId = "WO-" + Math.floor(Math.random() * 9000 + 1000);
  const currentUser = (typeof currentActiveUser !== 'undefined' && currentActiveUser.name) ? currentActiveUser.name : 'Cabella Staff';
  const timeNow = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ', Today';

  const newOrder = {
    id: randId,
    projectName: projectName,
    customer: customer,
    poNumber: poNumber || 'PO-PENDING',
    invoiceNumber: invoiceNumber || 'INV-PENDING',
    vendorName: vendorName || 'Approved Supplier',
    itemsSummary: itemsSummary || 'Standard cabinet/stone materials package',
    status: status,
    statusLabel: statusLabel,
    binNumber: binNumber,
    missingItems: '',
    updatedBy: currentUser,
    updatedAt: timeNow,
    lifecycleStage: 6,
    notes: [
      { author: currentUser, text: `New order logged in warehouse feed for ${customer}.`, timestamp: timeNow }
    ]
  };

  const orders = getWarehouseOrders();
  orders.unshift(newOrder);
  saveWarehouseOrders(orders);
  closeNewWarehouseOrderModal();
  if (typeof showToast === 'function') showToast(`✅ New warehouse order created for ${projectName}!`);
}

function postWarehouseOrderNote(orderId, inputId) {
  const inputEl = document.getElementById(inputId);
  if (!inputEl) return;
  const text = inputEl.value.trim();
  if (!text) return;

  const orders = getWarehouseOrders();
  const order = orders.find(o => o.id === orderId);
  if (!order) return;

  if (!order.notes) order.notes = [];
  const currentUser = (typeof currentActiveUser !== 'undefined' && currentActiveUser.name) ? currentActiveUser.name : 'Cabella Staff';
  const timeNow = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ', Today';

  order.notes.push({
    author: currentUser,
    text: text,
    timestamp: timeNow
  });
  order.updatedBy = currentUser;
  order.updatedAt = timeNow;

  inputEl.value = '';
  saveWarehouseOrders(orders);
  if (typeof showToast === 'function') showToast(`💬 Note posted to ${order.projectName}!`);
}


