function getDispatchData() {
  try {
    const raw = localStorage.getItem('cabellaDispatchData_v2');
    if (raw) return JSON.parse(raw);
  } catch(e) {}
  localStorage.setItem('cabellaDispatchData_v2', JSON.stringify(DEFAULT_DISPATCH_DATA));
  return DEFAULT_DISPATCH_DATA;
}

function saveDispatchData(data) {
  localStorage.setItem('cabellaDispatchData_v2', JSON.stringify(data));
  renderAllDispatchViews();
}

function switchFulfillmentMainTab(tabKey) {
  const data = getDispatchData();
  data.activeFulfillmentTab = tabKey;
  saveDispatchData(data);
}

function switchDispatchDate(dateStr) {
  const data = getDispatchData();
  data.currentManifestDate = dateStr;
  saveDispatchData(data);
}

function switchDispatchTruckTab(truckId) {
  const data = getDispatchData();
  data.activeTruckTab = truckId;
  saveDispatchData(data);
}

function toggleDispatchLock(dateStr) {
  const data = getDispatchData();
  const manifest = data.manifests[dateStr || data.currentManifestDate];
  if (!manifest) return;

  const user = (typeof currentActiveUser !== 'undefined') ? currentActiveUser.name : 'Authorized Staff';
  manifest.isLocked = !manifest.isLocked;
  if (manifest.isLocked) {
    manifest.lockedAt = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) + ' at ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    manifest.lockedBy = user;
    if (typeof showToast === 'function') showToast('🔒 Manifest Locked at 6:00 PM Cutoff. Orders dispatched.');
  } else {
    manifest.lockedAt = '';
    manifest.lockedBy = '';
    if (typeof showToast === 'function') showToast('🔓 Manifest UNLOCKED. Project Managers & Mayra can edit POs.');
  }
  saveDispatchData(data);
}

function findVendorPickupAddress(vendorInput) {
  if (!vendorInput) return '';
  const raw = String(vendorInput).trim();
  if (!raw) return '';
  const clean = raw.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (!clean) return '';

  // 1. Direct exact lookup in VENDOR_ADDRESS_BOOK
  if (VENDOR_ADDRESS_BOOK[raw]) return VENDOR_ADDRESS_BOOK[raw];

  // 2. Normalized exact match (ignoring spaces & special chars)
  for (const [key, addr] of Object.entries(VENDOR_ADDRESS_BOOK)) {
    const cleanKey = key.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (clean === cleanKey) return addr;
  }

  // 3. Substring match against VENDOR_ADDRESS_BOOK keys
  for (const [key, addr] of Object.entries(VENDOR_ADDRESS_BOOK)) {
    const cleanKey = key.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (clean.length >= 2 && (clean.includes(cleanKey) || cleanKey.includes(clean))) {
      return addr;
    }
  }

  // 4. Word-level match (e.g. "grand wood" matches "grandwood")
  const words = raw.toLowerCase().split(/\s+/).filter(w => w.length >= 3);
  if (words.length > 0) {
    for (const [key, addr] of Object.entries(VENDOR_ADDRESS_BOOK)) {
      const kLower = key.toLowerCase().replace(/[^a-z0-9]/g, '');
      if (words.every(w => kLower.includes(w)) || words.some(w => w.length >= 4 && kLower.includes(w))) {
        return addr;
      }
    }
  }

  // 5. Dynamic search in BASE_DATA.vendors
  if (typeof BASE_DATA !== 'undefined' && Array.isArray(BASE_DATA.vendors)) {
    for (const v of BASE_DATA.vendors) {
      if (!v.address) continue;
      const vNameClean = (v.name || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const vCompClean = (v.company || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      if (clean === vNameClean || clean === vCompClean) return v.address;
      if (clean.length >= 3 && (clean.includes(vNameClean) || vNameClean.includes(clean) || clean.includes(vCompClean) || vCompClean.includes(clean))) {
        return v.address;
      }
    }
  }

  return '';
}

function populateVendorDatalists() {
  const datalist = document.getElementById('manifestVendorDatalist');
  if (!datalist) return;

  const entries = new Map();
  for (const [name, addr] of Object.entries(VENDOR_ADDRESS_BOOK)) {
    // Only include primary clean vendor names in datalist
    if (!entries.has(name)) entries.set(name, addr);
  }
  if (typeof BASE_DATA !== 'undefined' && Array.isArray(BASE_DATA.vendors)) {
    for (const v of BASE_DATA.vendors) {
      if (v.name && !entries.has(v.name)) entries.set(v.name, v.address || '');
    }
  }

  datalist.innerHTML = Array.from(entries.entries())
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([name, addr]) => `<option value="${esc(name)}">${addr ? esc(addr) : ''}</option>`)
    .join('');
}

function autoFillVendorAddressInForm(inputEl, targetAddressId) {
  const val = (inputEl.value || '').trim();
  const target = document.getElementById(targetAddressId);
  if (!target) return;

  const resolved = findVendorPickupAddress(val);
  if (resolved) {
    target.value = resolved;
    if (targetAddressId === 'manifestPoAddress') {
      const notice = document.getElementById('manifestPoAddressNotice');
      if (notice) {
        notice.style.display = 'inline-flex';
        notice.innerHTML = `<span>✓ Auto-filled: <strong>${esc(resolved.length > 35 ? resolved.slice(0, 35) + '...' : resolved)}</strong></span>`;
      }
      target.style.borderColor = '#10b981';
      target.style.backgroundColor = '#f0fdf4';
      setTimeout(() => {
        target.style.borderColor = '#cbd5e1';
        target.style.backgroundColor = '#ffffff';
      }, 1200);
    }
  }
}

function openAddPoToManifestModal(defaultTruckId) {
  const data = getDispatchData();
  const manifest = data.manifests[data.currentManifestDate];
  if (!manifest) return;

  const modal = document.getElementById('addPoToManifestModal');
  if (!modal) return;

  // Populate vendor datalist for instant autocomplete
  populateVendorDatalists();

  // Populate truck select options
  const truckSelect = document.getElementById('manifestPoTruckSelect');
  if (truckSelect) {
    truckSelect.innerHTML = manifest.trucks.map(t => 
      `<option value="${t.id}" ${t.id === (defaultTruckId || data.activeTruckTab) ? 'selected' : ''}>${t.icon} ${esc(t.name)} (${t.driverName || 'Driver'})</option>`
    ).join('');
  }

  // Reset fields
  const cName = document.getElementById('manifestPoCompanyName');
  const cAddr = document.getElementById('manifestPoAddress');
  const vInv = document.getElementById('manifestPoVendorInv');
  const poNum = document.getElementById('manifestPoNumber');
  const cInv = document.getElementById('manifestPoCustInv');
  const qty = document.getElementById('manifestPoQty');
  const notes = document.getElementById('manifestPoNotes');
  const notice = document.getElementById('manifestPoAddressNotice');

  if (cName) cName.value = '';
  if (cAddr) {
    cAddr.value = '';
    cAddr.style.borderColor = '#cbd5e1';
    cAddr.style.backgroundColor = '#ffffff';
  }
  if (vInv) vInv.value = '';
  if (poNum) poNum.value = '';
  if (cInv) cInv.value = '';
  if (qty) qty.value = '';
  if (notes) notes.value = '';
  if (notice) {
    notice.style.display = 'none';
    notice.innerHTML = '';
  }

  modal.style.display = 'flex';
  if (cName) setTimeout(() => cName.focus(), 50);
}

function closeAddPoToManifestModal() {
  const modal = document.getElementById('addPoToManifestModal');
  if (modal) modal.style.display = 'none';
}

function saveNewPoToManifest() {
  const data = getDispatchData();
  const manifest = data.manifests[data.currentManifestDate];
  if (!manifest) return;

  const truckId = document.getElementById('manifestPoTruckSelect')?.value || 'all_in';
  const companyName = (document.getElementById('manifestPoCompanyName')?.value || '').trim();
  let address = (document.getElementById('manifestPoAddress')?.value || '').trim();
  const vendorInv = (document.getElementById('manifestPoVendorInv')?.value || '').trim() || '—';
  const poNumber = (document.getElementById('manifestPoNumber')?.value || '').trim();
  const custInv = (document.getElementById('manifestPoCustInv')?.value || '').trim() || '—';
  const qty = (document.getElementById('manifestPoQty')?.value || '').trim() || '—';
  const notes = (document.getElementById('manifestPoNotes')?.value || '').trim() || 'Added to manifest';
  const status = document.getElementById('manifestPoStatusSelect')?.value || 'Scheduled';

  if (!companyName) {
    alert('Please enter the Company / Vendor Name (e.g. HomeCo, Grandwood, Duko).');
    return;
  }
  if (!poNumber) {
    alert('Please enter the PO # (e.g. 3210).');
    return;
  }

  if (!address) {
    address = findVendorPickupAddress(companyName) || 'California / Local Supplier Warehouse';
  }

  let truck = manifest.trucks.find(t => t.id === truckId);
  if (!truck) {
    truck = manifest.trucks[0];
  }

  const newRow = {
    id: 'row-' + Date.now(),
    stop: truck.rows.length + 1,
    companyName: companyName,
    address: address,
    vendorInv: vendorInv,
    poNumber: poNumber,
    custInv: custInv,
    qty: qty,
    notes: notes,
    status: status,
    lastUpdated: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  };

  truck.rows.push(newRow);
  saveDispatchData(data);
  closeAddPoToManifestModal();
  if (typeof showToast === 'function') showToast(`✅ PO #${poNumber} (${companyName}) added to ${truck.name}!`);
}

function quickAddInlinePoToManifest() {
  const data = getDispatchData();
  const manifest = data.manifests[data.currentManifestDate];
  if (!manifest) return;

  const targetTruckId = data.activeTruckTab === 'master' ? 'all_in' : data.activeTruckTab;
  const truck = manifest.trucks.find(t => t.id === targetTruckId) || manifest.trucks[0];

  const cNameEl = document.getElementById('inlinePoCompanyName');
  const poEl = document.getElementById('inlinePoNumber');
  const vInvEl = document.getElementById('inlinePoVendorInv');
  const cInvEl = document.getElementById('inlinePoCustInv');
  const qtyEl = document.getElementById('inlinePoQty');
  const notesEl = document.getElementById('inlinePoNotes');

  const companyName = (cNameEl?.value || '').trim();
  const poNumber = (poEl?.value || '').trim();
  const vendorInv = (vInvEl?.value || '').trim() || '—';
  const custInv = (cInvEl?.value || '').trim() || '—';
  const qty = (qtyEl?.value || '').trim() || '—';
  const notes = (notesEl?.value || '').trim() || '—';

  if (!companyName || !poNumber) {
    alert('Please enter at least Company Name and PO # to quick add.');
    return;
  }

  let address = (document.getElementById('inlineHiddenAddr')?.value || '').trim();
  if (!address) {
    address = findVendorPickupAddress(companyName) || 'California / Local Supplier Warehouse';
  }

  const newRow = {
    id: 'row-' + Date.now(),
    stop: truck.rows.length + 1,
    companyName: companyName,
    address: address,
    vendorInv: vendorInv,
    poNumber: poNumber,
    custInv: custInv,
    qty: qty,
    notes: notes,
    status: 'Scheduled',
    lastUpdated: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  };

  truck.rows.push(newRow);
  saveDispatchData(data);

  if (cNameEl) cNameEl.value = '';
  if (poEl) poEl.value = '';
  if (vInvEl) vInvEl.value = '';
  if (cInvEl) cInvEl.value = '';
  if (qtyEl) qtyEl.value = '';
  if (notesEl) notesEl.value = '';

  if (typeof showToast === 'function') showToast(`➕ PO #${poNumber} added to ${truck.name} whiteboard!`);
}

function updateManifestRowStatus(rowId, newStatus) {
  const data = getDispatchData();
  const manifest = data.manifests[data.currentManifestDate];
  if (!manifest) return;

  for (const truck of manifest.trucks) {
    const row = truck.rows.find(r => r.id === rowId);
    if (row) {
      row.status = newStatus;
      row.lastUpdated = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      saveDispatchData(data);
      if (typeof showToast === 'function') showToast(`⚡ PO #${row.poNumber} status updated to "${newStatus}"`);
      return;
    }
  }
}

function deleteManifestRow(rowId) {
  if (!confirm('Are you sure you want to remove this PO pickup from the manifest?')) return;

  const data = getDispatchData();
  const manifest = data.manifests[data.currentManifestDate];
  if (!manifest) return;

  for (const truck of manifest.trucks) {
    const idx = truck.rows.findIndex(r => r.id === rowId);
    if (idx !== -1) {
      const removed = truck.rows.splice(idx, 1)[0];
      // Renumber stops
      truck.rows.forEach((r, i) => r.stop = i + 1);
      saveDispatchData(data);
      if (typeof showToast === 'function') showToast(`🗑️ PO #${removed.poNumber} removed from manifest.`);
      return;
    }
  }
}

function moveManifestRowTruck(rowId, targetTruckId) {
  const data = getDispatchData();
  const manifest = data.manifests[data.currentManifestDate];
  if (!manifest) return;

  let sourceRow = null;
  let sourceTruck = null;

  for (const truck of manifest.trucks) {
    const idx = truck.rows.findIndex(r => r.id === rowId);
    if (idx !== -1) {
      sourceTruck = truck;
      sourceRow = truck.rows.splice(idx, 1)[0];
      truck.rows.forEach((r, i) => r.stop = i + 1);
      break;
    }
  }

  if (!sourceRow) return;

  const destTruck = manifest.trucks.find(t => t.id === targetTruckId);
  if (!destTruck) return;

  sourceRow.stop = destTruck.rows.length + 1;
  sourceRow.lastUpdated = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  destTruck.rows.push(sourceRow);

  saveDispatchData(data);
  if (typeof showToast === 'function') showToast(`🚚 PO #${sourceRow.poNumber} moved to ${destTruck.name}!`);
}

