function handleTruckLoadPhotoUpload(inputEl) {
  if (!inputEl.files || inputEl.files.length === 0 || !activeSigningOrder) return;
  const file = inputEl.files[0];
  const reader = new FileReader();

  reader.onload = function(e) {
    const dataUrl = e.target.result;
    const store = getPhotoProofStore();
    if (!store[activeSigningOrder.id]) {
      store[activeSigningOrder.id] = { driverPickupPhotos: [], warehouseDropoffPhotos: [], warehousePickingPhotos: [], truckLoadedPhotos: [], clientPickupRelease: null };
    }
    if (!store[activeSigningOrder.id].truckLoadedPhotos) {
      store[activeSigningOrder.id].truckLoadedPhotos = [];
    }

    store[activeSigningOrder.id].truckLoadedPhotos.push({
      id: 'photo-' + Date.now(),
      url: dataUrl,
      caption: "Client Truck Loaded Photo",
      takenAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      takenBy: "Chuy (Warehouse)"
    });

    savePhotoProofStore(store);
    renderTruckLoadedPhotosList();
    if (typeof showToast === 'function') showToast('📷 Client loaded truck photo added!');
  };

  reader.readAsDataURL(file);
}

function saveClientSignatureRelease() {
  if (!activeSigningOrder) return;

  const clientName = (document.getElementById('signClientName')?.value || '').trim();
  const companyName = (document.getElementById('signClientCompany')?.value || '').trim();
  const phone = (document.getElementById('signClientPhone')?.value || '').trim();
  const plate = (document.getElementById('signClientPlate')?.value || '').trim();
  const ackChecked = document.getElementById('signAckCheckbox')?.checked;

  if (!clientName) {
    alert('Please enter the client / driver printed name.');
    return;
  }

  if (!signatureHasStrokes && !signaturePadCanvas) {
    alert('Please have the client sign their signature on the pad using their finger or mouse.');
    return;
  }

  if (!ackChecked) {
    alert('Please verify that the client acknowledges receiving all materials in good condition.');
    return;
  }

  const signatureDataUrl = signaturePadCanvas.toDataURL('image/png');
  const store = getPhotoProofStore();
  if (!store[activeSigningOrder.id]) {
    store[activeSigningOrder.id] = { driverPickupPhotos: [], warehouseDropoffPhotos: [], warehousePickingPhotos: [], truckLoadedPhotos: [], clientPickupRelease: null };
  }

  const staffUser = (typeof currentActiveUser !== 'undefined') ? currentActiveUser.name : 'Chuy (Warehouse Manager)';

  store[activeSigningOrder.id].clientPickupRelease = {
    clientName: clientName,
    companyName: companyName || activeSigningOrder.customer,
    phone: phone || 'N/A',
    vehiclePlate: plate || 'Standard Vehicle / Truck',
    signedAt: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) + ' at ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    signedByStaff: staffUser,
    signatureDataUrl: signatureDataUrl,
    truckLoadedPhotos: store[activeSigningOrder.id].truckLoadedPhotos || []
  };

  // Update order status to Completed & mark lifecycle stage 7 (Picked up / Delivered)
  const orders = getWarehouseOrders();
  const ord = orders.find(o => o.id === activeSigningOrder.id);
  if (ord) {
    ord.status = 'completed';
    ord.statusLabel = 'Picked Up & Signed by Client';
    ord.lifecycleStage = 7;
    ord.updatedBy = staffUser;
    ord.updatedAt = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    ord.notes.push({
      author: staffUser,
      text: `Client ${clientName} (${companyName || activeSigningOrder.customer}) loaded truck, signed digital release waiver, and departed.`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    saveWarehouseOrders(orders);
  }

  savePhotoProofStore(store);
  closeClientSignatureModal();
  if (typeof showToast === 'function') showToast(`✍️ Signed Bill of Lading & Release saved for ${clientName}!`);

  // Open receipt view
  setTimeout(() => {
    openPodReceiptModal(activeSigningOrder.id);
  }, 400);
}

