function buildDispatchWhiteboardHtml(context) {
  const data = getDispatchData();
  const currentDate = data.currentManifestDate || '2026-08-15';
  const manifest = data.manifests[currentDate] || data.manifests['2026-08-15'];
  if (!manifest) return '<div style="padding:20px; text-align:center">No manifest selected.</div>';

  const activeTruckId = data.activeTruckTab || 'all_in';
  const isMaster = activeTruckId === 'master';

  // Calculate stats
  let totalStops = 0;
  let stoneCount = 0;
  let activeTruckCount = manifest.trucks.length;

  manifest.trucks.forEach(t => {
    totalStops += t.rows.length;
    t.rows.forEach(r => {
      if (r.qty && r.qty.toLowerCase().includes('stone')) {
        const match = r.qty.match(/\d+/);
        if (match) stoneCount += parseInt(match[0], 10);
      }
    });
  });

  const currentTruck = manifest.trucks.find(t => t.id === activeTruckId) || manifest.trucks[0];
  const displayedRows = isMaster 
    ? manifest.trucks.flatMap(t => t.rows.map(r => ({ ...r, carrierName: t.name, carrierIcon: t.icon, carrierId: t.id })))
    : (currentTruck ? currentTruck.rows.map(r => ({ ...r, carrierName: currentTruck.name, carrierIcon: currentTruck.icon, carrierId: currentTruck.id })) : []);

  // Delivery cycle date buttons
  const datePillsHtml = Object.keys(data.manifests).map(dStr => {
    const m = data.manifests[dStr];
    const isAct = dStr === currentDate;
    return `
      <button onclick="switchDispatchDate('${dStr}')" style="background: ${isAct ? '#0284c7' : '#ffffff'}; color: ${isAct ? '#ffffff' : '#334155'}; border: 1px solid ${isAct ? '#0284c7' : '#cbd5e1'}; font-weight: 800; font-size: 12px; padding: 7px 14px; border-radius: 20px; cursor: pointer; display: flex; align-items: center; gap: 6px; box-shadow: ${isAct ? '0 2px 6px rgba(2,132,199,0.25)' : 'none'}; transition: all 0.2s">
        <span>📅</span>
        <span>${m.deliveryDay} Delivery (${m.deliveryDate})</span>
        <span style="font-size: 10px; background: ${isAct ? 'rgba(255,255,255,0.25)' : '#e2e8f0'}; padding: 2px 6px; border-radius: 10px">${m.pickupDay} Pickup</span>
      </button>
    `;
  }).join('');

  // Truck tabs
  const truckTabsHtml = manifest.trucks.map(t => {
    const isAct = t.id === activeTruckId;
    return `
      <button onclick="switchDispatchTruckTab('${t.id}')" style="background: ${isAct ? '#0f172a' : '#f8fafc'}; color: ${isAct ? '#ffffff' : '#475569'}; border: 1px solid ${isAct ? '#0f172a' : '#cbd5e1'}; font-weight: 800; font-size: 12.5px; padding: 9px 16px; border-radius: 8px 8px 0 0; cursor: pointer; display: flex; align-items: center; gap: 8px; border-bottom: ${isAct ? '2px solid #0f172a' : '1px solid #cbd5e1'}; transition: all 0.15s">
        <span>${t.icon}</span>
        <span>${esc(t.name)}</span>
        <span style="background: ${isAct ? '#0284c7' : '#e2e8f0'}; color: ${isAct ? '#fff' : '#0f172a'}; font-size: 11px; font-weight: 800; padding: 2px 7px; border-radius: 12px">${t.rows.length} POs</span>
      </button>
    `;
  }).join('');

  const masterTabHtml = `
    <button onclick="switchDispatchTruckTab('master')" style="background: ${isMaster ? '#0f172a' : '#f8fafc'}; color: ${isMaster ? '#ffffff' : '#475569'}; border: 1px solid ${isMaster ? '#0f172a' : '#cbd5e1'}; font-weight: 800; font-size: 12.5px; padding: 9px 16px; border-radius: 8px 8px 0 0; cursor: pointer; display: flex; align-items: center; gap: 8px; border-bottom: ${isMaster ? '2px solid #0f172a' : '1px solid #cbd5e1'}">
      <span>📋</span>
      <span>Combined Master Board</span>
      <span style="background: ${isMaster ? '#0284c7' : '#e2e8f0'}; color: ${isMaster ? '#fff' : '#0f172a'}; font-size: 11px; font-weight: 800; padding: 2px 7px; border-radius: 12px">${totalStops} Total</span>
    </button>
  `;

  // Lock status banner
  const lockStatusBadge = manifest.isLocked 
    ? `<span style="background: #fee2e2; color: #991b1b; border: 1px solid #fecaca; font-weight: 800; font-size: 12px; padding: 5px 12px; border-radius: 20px; display: inline-flex; align-items: center; gap: 6px">🔒 6:00 PM CUTOFF: LOCKED (${manifest.lockedAt || 'Aug 14, 6:00 PM'})</span>`
    : `<span style="background: #dcfce7; color: #166534; border: 1px solid #bbf7d0; font-weight: 800; font-size: 12px; padding: 5px 12px; border-radius: 20px; display: inline-flex; align-items: center; gap: 6px">🟢 OPEN FOR POs (Cutoff: ${manifest.cutoffTime} on ${manifest.pickupDay})</span>`;

  // Whiteboard table rows
  let tableRowsHtml = '';
  if (displayedRows.length === 0) {
    tableRowsHtml = `
      <tr>
        <td colspan="9" style="text-align: center; padding: 36px 20px; color: #64748b; background: #f8fafc">
          <div style="font-size: 24px; margin-bottom: 6px">🚚</div>
          <div style="font-weight: 800; color: #0f172a; font-size: 15px">No PO pickups on this truck manifest yet.</div>
          <div style="font-size: 13px; color: #64748b; margin-top: 4px">Use the quick add form below or click "+ Add PO to Manifest" to schedule a pickup.</div>
        </td>
      </tr>
    `;
  } else {
    tableRowsHtml = displayedRows.map((r, idx) => {
      let statusBg = '#fefce8', statusColor = '#854d0e', statusBorder = '#fef08a';
      if (r.status === 'Picked Up' || r.status === 'In Transit') {
        statusBg = '#e0f2fe'; statusColor = '#0369a1'; statusBorder = '#bae6fd';
      } else if (r.status === 'Received at Cabella') {
        statusBg = '#dcfce7'; statusColor = '#166534'; statusBorder = '#bbf7d0';
      }

      const isStone = r.qty && r.qty.toLowerCase().includes('stone');
      const googleMapsUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(r.companyName + ' ' + r.address)}`;

      const moveOptions = manifest.trucks
        .filter(t => t.id !== r.carrierId)
        .map(t => `<option value="${t.id}">Move to ${t.name}</option>`)
        .join('');

      return `
        <tr style="border-bottom: 1px solid #e2e8f0; transition: background 0.15s; background: #ffffff" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='#ffffff'">
          <td style="padding: 12px 10px; text-align: center; font-weight: 900; color: #0f172a; font-size: 13px">
            ${r.stop}
          </td>
          <td style="padding: 12px 10px">
            <div style="font-weight: 800; font-size: 13.5px; color: #0f172a">${esc(r.companyName)}</div>
            ${isMaster ? `<span style="font-size: 10.5px; background: #e2e8f0; color: #334155; padding: 2px 6px; border-radius: 4px; font-weight: 700">${r.carrierIcon} ${esc(r.carrierName)}</span>` : ''}
          </td>
          <td style="padding: 12px 10px; font-size: 12px; color: #475569; max-width: 240px">
            <div>${esc(r.address)}</div>
            <a href="${googleMapsUrl}" target="_blank" rel="noopener noreferrer" style="color: #0284c7; text-decoration: none; font-size: 11px; font-weight: 700; display: inline-flex; align-items: center; gap: 3px; margin-top: 2px">
              <span>🗺️ Open in Maps ↗</span>
            </a>
          </td>
          <td style="padding: 12px 10px; font-size: 12.5px; font-weight: 700; color: #334155">
            ${r.vendorInv !== '—' ? `<span style="background: #f1f5f9; padding: 3px 7px; border-radius: 4px; border: 1px solid #e2e8f0">${esc(r.vendorInv)}</span>` : '<span style="color:#94a3b8">—</span>'}
          </td>
          <td style="padding: 12px 10px">
            <span style="font-size: 13px; font-weight: 900; color: #0f766e; background: #ccfbf1; padding: 4px 8px; border-radius: 6px; border: 1px solid #99f6e4">
              PO #${esc(r.poNumber)}
            </span>
          </td>
          <td style="padding: 12px 10px; font-size: 12px; font-weight: 700; color: #475569">
            ${r.custInv !== '—' ? `<span style="color: #0284c7; font-weight: 800">#${esc(r.custInv)}</span>` : '<span style="color:#94a3b8">—</span>'}
          </td>
          <td style="padding: 12px 10px; font-size: 12px">
            ${isStone ? `<span style="background: #fef3c7; color: #92400e; font-weight: 800; padding: 3px 8px; border-radius: 6px; border: 1px solid #fde68a; display: inline-block; margin-bottom: 2px">💎 ${esc(r.qty)}</span>` : (r.qty !== '—' ? `<strong style="color:#0f172a">${esc(r.qty)}</strong>` : '')}
            <div style="color: #475569; font-size: 11.5px; line-height: 1.2">${esc(r.notes !== '—' ? r.notes : '')}</div>
          </td>
          <td style="padding: 12px 10px">
            <select onchange="updateManifestRowStatus('${r.id}', this.value)" style="background: ${statusBg}; color: ${statusColor}; border: 1px solid ${statusBorder}; font-weight: 800; font-size: 11.5px; padding: 5px 8px; border-radius: 6px; cursor: pointer; outline: none">
              <option value="Scheduled" ${r.status === 'Scheduled' ? 'selected' : ''}>🟡 Scheduled</option>
              <option value="Picked Up" ${r.status === 'Picked Up' ? 'selected' : ''}>🚛 Picked Up</option>
              <option value="In Transit" ${r.status === 'In Transit' ? 'selected' : ''}>🚚 In Transit</option>
              <option value="Received at Cabella" ${r.status === 'Received at Cabella' ? 'selected' : ''}>🟢 Received at Warehouse</option>
            </select>
          </td>
          <td style="padding: 12px 10px">
            <button onclick="openPoPhotoModal('${r.poNumber}', '${esc(r.companyName)} — PO #${r.poNumber}', 'driverPickupPhotos')" style="background: #f0f9ff; color: #0284c7; border: 1px solid #bae6fd; font-size: 11px; font-weight: 800; padding: 4px 8px; border-radius: 6px; cursor: pointer; display: flex; align-items: center; gap: 3px; white-space: nowrap">
              <span>📷</span> <span>Photos</span>
            </button>
          </td>
          <td style="padding: 12px 10px; text-align: right; white-space: nowrap">
            <div style="display: flex; align-items: center; justify-content: flex-end; gap: 6px">
              <button onclick="syncManifestPoToWarehouse('${r.id}')" title="Sync to Warehouse Staging Bin" style="background: #f0fdf4; color: #166534; border: 1px solid #bbf7d0; padding: 4px 8px; border-radius: 6px; font-size: 11px; font-weight: 700; cursor: pointer">
                📦 Stage
              </button>
              <select onchange="if(this.value) { moveManifestRowTruck('${r.id}', this.value); this.value=''; }" style="background: #f8fafc; border: 1px solid #cbd5e1; font-size: 11px; padding: 4px 6px; border-radius: 6px; cursor: pointer" title="Move to another truck">
                <option value="">Move ➔</option>
                ${moveOptions}
              </select>
              <button onclick="deleteManifestRow('${r.id}')" title="Remove from Manifest" style="background: #fff1f2; color: #9f1239; border: 1px solid #fecdd3; padding: 4px 7px; border-radius: 6px; font-size: 11px; cursor: pointer">
                ✕
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  return `
    <div style="background: #ffffff; border: 2px solid #0284c7; border-radius: 14px; padding: 22px; margin-bottom: 24px; box-shadow: 0 4px 16px rgba(2, 132, 199, 0.08)">
      
      <!-- Top Header & Rules Banner -->
      <div style="display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 14px; margin-bottom: 18px; padding-bottom: 16px; border-bottom: 1px solid #e2e8f0">
        <div>
          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 6px">
            <span class="badge" style="background: #0284c7; color: #ffffff; font-weight: 800; font-size: 11px; padding: 4px 10px; border-radius: 6px">🚚 DIGITAL WHITEBOARD & DISPATCH HUB</span>
            <span style="background: #f0fdf4; color: #166534; font-weight: 800; font-size: 11px; padding: 3px 9px; border-radius: 6px; border: 1px solid #bbf7d0">📅 3 DELIVERY DAYS: TUESDAYS · THURSDAYS · SATURDAYS</span>
            ${lockStatusBadge}
          </div>
          <h2 style="margin: 0 0 4px; font-size: 22px; font-weight: 900; color: #0f172a; display: flex; align-items: center; gap: 8px">
            <span>📋</span> <span>Cabella Delivery & Pickup Dispatch Board</span>
          </h2>
          <p style="margin: 0; font-size: 13.5px; color: #475569; line-height: 1.4">
            Enterprise digital whiteboard for Project Managers, Logistics Coordinators & Warehouse Operations. Pickups happen the day prior in California/Local and deliver to Las Vegas. Cutoff locks at <strong>6:00 PM on pickup day</strong>.
          </p>
        </div>

        <!-- Main Action Buttons -->
        <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap">
          <button class="btn" onclick="toggleDispatchLock('${manifest.deliveryDate}')" style="background: ${manifest.isLocked ? '#fff1f2' : '#f0fdf4'}; color: ${manifest.isLocked ? '#991b1b' : '#166534'}; border: 1px solid ${manifest.isLocked ? '#fecaca' : '#bbf7d0'}; font-weight: 800; font-size: 12.5px; padding: 8px 14px; border-radius: 8px; cursor: pointer; display: flex; align-items: center; gap: 6px">
            <span>${manifest.isLocked ? '🔓 Unlock to Edit' : '🔒 Lock at 6 PM'}</span>
          </button>
          <button class="btn" onclick="openAddPoToManifestModal()" style="background: #0284c7; color: #ffffff; font-weight: 800; font-size: 12.5px; padding: 8px 14px; border-radius: 8px; border: 0; cursor: pointer; display: flex; align-items: center; gap: 6px; box-shadow: 0 2px 6px rgba(2,132,199,0.25)">
            <span>➕</span> <span>Add PO to Manifest</span>
          </button>
          <button class="btn secondary" onclick="openAddNewTruckModal()" style="background: #f8fafc; color: #0f172a; border: 1px solid #cbd5e1; font-weight: 700; font-size: 12.5px; padding: 8px 12px; border-radius: 8px; cursor: pointer; display: flex; align-items: center; gap: 5px">
            <span>🚐</span> <span>+ Add Truck</span>
          </button>
          <button class="btn secondary" onclick="printDeliveryManifest('${activeTruckId}')" style="background: #ffffff; color: #334155; border: 1px solid #cbd5e1; font-weight: 700; font-size: 12.5px; padding: 8px 12px; border-radius: 8px; cursor: pointer; display: flex; align-items: center; gap: 5px" title="Print Driver Sheet (Matching Cabella Template)">
            <span>🖨️</span> <span>Print Sheet</span>
          </button>
          <button class="btn secondary" onclick="openSmsDispatchModal('${activeTruckId}')" style="background: #ffffff; color: #334155; border: 1px solid #cbd5e1; font-weight: 700; font-size: 12.5px; padding: 8px 12px; border-radius: 8px; cursor: pointer; display: flex; align-items: center; gap: 5px" title="Send Stops to Driver via SMS / RingCentral">
            <span>📱</span> <span>SMS Dispatch</span>
          </button>
          <button class="btn secondary" onclick="exportManifestCsv('${activeTruckId}')" style="background: #ffffff; color: #334155; border: 1px solid #cbd5e1; font-weight: 700; font-size: 12.5px; padding: 8px 12px; border-radius: 8px; cursor: pointer" title="Download Excel / CSV">
            <span>📥</span> <span>CSV</span>
          </button>
        </div>
      </div>

      <!-- Delivery Schedule Date Selector & Rule Explanation -->
      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px 16px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px">
        <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap">
          <span style="font-size: 12px; font-weight: 800; color: #475569; text-transform: uppercase">SELECT DELIVERY RUN:</span>
          ${datePillsHtml}
        </div>
        <div style="font-size: 12px; color: #64748b; font-weight: 600">
          💡 <strong>Fulfillment Rule:</strong> Saturday trucks carry orders placed Thursday + Friday early additions.
        </div>
      </div>

      <!-- Quick Metrics Summary Bar -->
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; margin-bottom: 16px">
        <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 10px 12px; text-align: center">
          <div style="font-size: 10.5px; font-weight: 800; color: #64748b; text-transform: uppercase">TOTAL PO PICKUPS</div>
          <div style="font-size: 18px; font-weight: 900; color: #0f172a; margin-top: 2px">${totalStops} POs Scheduled</div>
        </div>
        <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 10px 12px; text-align: center">
          <div style="font-size: 10.5px; font-weight: 800; color: #64748b; text-transform: uppercase">ACTIVE CARRIER TRUCKS</div>
          <div style="font-size: 18px; font-weight: 900; color: #0284c7; margin-top: 2px">${activeTruckCount} Trucks Assigned</div>
        </div>
        <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 10px 12px; text-align: center">
          <div style="font-size: 10.5px; font-weight: 800; color: #64748b; text-transform: uppercase">PREFAB COUNTERTOP STONES</div>
          <div style="font-size: 18px; font-weight: 900; color: #b45309; margin-top: 2px">${stoneCount} Slabs Scheduled</div>
        </div>
        <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 10px 12px; text-align: center">
          <div style="font-size: 10.5px; font-weight: 800; color: #64748b; text-transform: uppercase">CUTOFF STATUS</div>
          <div style="font-size: 16px; font-weight: 900; color: ${manifest.isLocked ? '#991b1b' : '#16a34a'}; margin-top: 2px">
            ${manifest.isLocked ? '🔒 Cutoff Locked' : '🟢 Open for Orders'}
          </div>
        </div>
      </div>

      <!-- Truck Carrier Tabs -->
      <div style="display: flex; gap: 6px; border-bottom: 1px solid #cbd5e1; overflow-x: auto; margin-bottom: 0">
        ${truckTabsHtml}
        ${masterTabHtml}
      </div>

      <!-- Whiteboard Table Container -->
      <div style="border: 1px solid #cbd5e1; border-top: 0; border-radius: 0 0 10px 10px; overflow-x: auto; background: #ffffff; margin-bottom: 16px">
        <table style="width: 100%; border-collapse: collapse; text-align: left; font-size: 13px">
          <thead>
            <tr style="background: #0f172a; color: #ffffff; font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.5px">
              <th style="padding: 12px 10px; width: 45px; text-align: center">Stop</th>
              <th style="padding: 12px 10px; width: 170px">Company Name</th>
              <th style="padding: 12px 10px">Company Address & GPS</th>
              <th style="padding: 12px 10px; width: 110px">Vendor Inv #</th>
              <th style="padding: 12px 10px; width: 100px">PO #</th>
              <th style="padding: 12px 10px; width: 95px">Cust Inv #</th>
              <th style="padding: 12px 10px; width: 150px">Qty / Notes</th>
              <th style="padding: 12px 10px; width: 140px">Status</th>
              <th style="padding: 12px 10px; width: 110px">📸 Photos</th>
              <th style="padding: 12px 10px; width: 140px; text-align: right">Actions</th>
            </tr>
          </thead>
          <tbody>
            ${tableRowsHtml}
          </tbody>
        </table>
      </div>

      <!-- Inline Fast-Add Row Form (Quick Data Entry for Mayra & PMs) -->
      <div style="background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 10px; padding: 14px 16px">
        <div style="font-size: 12px; font-weight: 800; color: #0f172a; margin-bottom: 8px; display: flex; align-items: center; gap: 6px">
          <span>⚡</span> <span>Quick Add PO to ${isMaster ? 'ALL IN Transport' : esc(currentTruck ? currentTruck.name : 'Active Truck')} Whiteboard:</span>
        </div>
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)) 120px; gap: 8px; align-items: center">
          <input id="inlinePoCompanyName" list="manifestVendorDatalist" placeholder="Vendor (e.g. HomeCo, Grandwood)" style="padding: 8px 10px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12.5px" oninput="autoFillVendorAddressInForm(this, 'inlineHiddenAddr')" onchange="autoFillVendorAddressInForm(this, 'inlineHiddenAddr')" onblur="autoFillVendorAddressInForm(this, 'inlineHiddenAddr')" onkeyup="autoFillVendorAddressInForm(this, 'inlineHiddenAddr')">
          <input id="inlinePoNumber" placeholder="PO # (e.g. 3212)" style="padding: 8px 10px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12.5px; font-weight: 700">
          <input id="inlinePoVendorInv" placeholder="Vendor Inv #" style="padding: 8px 10px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12.5px">
          <input id="inlinePoCustInv" placeholder="Cust Inv #" style="padding: 8px 10px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12.5px">
          <input id="inlinePoQty" placeholder="Qty / Stones (e.g. 4 stones)" style="padding: 8px 10px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12.5px">
          <input id="inlinePoNotes" placeholder="Notes (e.g. White Shaker)" style="padding: 8px 10px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12.5px">
          <button onclick="quickAddInlinePoToManifest()" style="background: #0284c7; color: #ffffff; font-weight: 800; font-size: 12.5px; padding: 8px 12px; border-radius: 6px; border: 0; cursor: pointer; white-space: nowrap">
            ➕ Add PO
          </button>
        </div>
        <input type="hidden" id="inlineHiddenAddr">
      </div>

    </div>
  `;
}


function openWarehouseInspectorModal() {
  const modal = document.getElementById('warehouseInspectorModal');
  if (modal) {
    modal.style.display = 'flex';
    if (typeof renderWarehouseFeed === 'function') renderWarehouseFeed();
  }
}

function closeWarehouseInspectorModal() {
  const modal = document.getElementById('warehouseInspectorModal');
  if (modal) modal.style.display = 'none';
}

// Global initialization hook
document.addEventListener('DOMContentLoaded', () => {
  renderAllDispatchViews();
  populateVendorDatalists();
});




