function submitInboundReceiving() {
  const vendor = document.getElementById('inboundVendorSelect').value;
  const poRef = document.getElementById('inboundPoRef').value;
  const sku = document.getElementById('inboundSkuSelect').value;
  const qty = Number(document.getElementById('inboundQty').value) || 0;
  const aisle = document.getElementById('inboundAisle').value;
  const rack = document.getElementById('inboundRack').value;
  const bin = document.getElementById('inboundBin').value;

  const invStore = getInventoryStore();
  let item = invStore.items.find(i => i.sku === sku);
  if (item) {
    item.onHand += qty;
    item.aisle = aisle;
    item.rack = rack;
    item.bin = bin;
    item.location = aisle.replace('Aisle ', '') + '-' + rack.replace('Rack ', '') + '-' + bin.replace('Bin ', '');
  }

  const uName = (typeof currentActiveUser !== 'undefined' && currentActiveUser.name) ? currentActiveUser.name : 'Chuy (Warehouse Mgr)';

  invStore.auditLog.unshift({
    id: 'LOG-' + Math.floor(Math.random()*9000 + 1000),
    timestamp: new Date().toLocaleString(),
    type: 'Inbound Received',
    sku: sku,
    location: aisle + ' · ' + rack + ' · ' + bin,
    qtyChange: '+' + qty,
    user: uName,
    ref: poRef + ' (' + vendor + ')'
  });

  saveInventoryStore(invStore);
  closeModal();
  showToast('🎉 Inbound Putaway Complete! Added +' + qty + ' units of ' + sku + ' to ' + bin);
  renderInventoryView();
}

