// PRINT QR LABELS (Formatted for standard thermal label printers or 8.5x11 sheets)
function printAllBinLabels() {
  const store = getInventoryStore();
  const items = store.items || [];

  const printWindow = window.open('', '_blank');
  if (!printWindow) {
    showToast('⚠️ Pop-up blocked. Please allow pop-ups to print QR bin labels.');
    return;
  }

  const labelHtml = `
    <!DOCTYPE html>
    <html>
    <head>
      <title>Cabella Warehouse Bin & Rack QR Labels</title>
      <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; padding: 20px; background: #fff; }
        .grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
        .label { border: 2px solid #000; padding: 14px; border-radius: 8px; page-break-inside: avoid; text-align: center; }
        .title { font-size: 18px; font-weight: 900; margin-bottom: 2px; }
        .loc { font-size: 22px; font-weight: 900; color: #0284c7; background: #f0f9ff; padding: 4px 8px; border-radius: 4px; display: inline-block; margin: 6px 0; }
        .qr-box { width: 100px; height: 100px; margin: 8px auto; border: 2px solid #333; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: bold; background: #f8fafc; }
        @media print {
          body { padding: 0; }
          button { display: none; }
        }
      </style>
    </head>
    <body>
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:20px; border-bottom:2px solid #333; padding-bottom:10px">
        <div>
          <h2 style="margin:0">Cabella Cabinets & Stone — Warehouse Bin QR Labels</h2>
          <div style="font-size:12px; color:#555">Thermal Label Ready · Print & affix to rack beam</div>
        </div>
        <button onclick="window.print()" style="background:#0284c7; color:#fff; font-weight:bold; font-size:14px; padding:10px 20px; border:0; border-radius:6px; cursor:pointer">🖨️ Print Labels</button>
      </div>

      <div class="grid">
        ${items.map(item => `
          <div class="label">
            <div class="title">${item.sku}</div>
            <div style="font-size:12px; color:#444">${item.name}</div>
            <div class="loc">${item.location} (${item.bin})</div>
            <div class="qr-box">
              [ QR CODE ]<br><span style="font-size:10px">${item.sku}</span>
            </div>
            <div style="font-size:11px; color:#666">${item.aisle} · ${item.rack}</div>
          </div>
        `).join('')}
      </div>
    </body>
    </html>
  `;

  printWindow.document.write(labelHtml);
  printWindow.document.close();
}

