function saveEditedInventoryItem(itemId) {
  const store = getInventoryStore();
  const item = store.items.find(i => i.id === itemId);
  if (!item) return;

  const oldOnHand = item.onHand;
  item.sku = document.getElementById('editInvSku').value.trim();
  item.name = document.getElementById('editInvName').value.trim();
  item.onHand = Number(document.getElementById('editInvOnHand').value) || 0;
  item.unitCost = Number(document.getElementById('editInvCost').value) || 0;
  item.salesVelocity3Day = Number(document.getElementById('editInvVel').value) || 0;
  item.aisle = document.getElementById('editInvAisle').value.trim();
  item.rack = document.getElementById('editInvRack').value.trim();
  item.bin = document.getElementById('editInvBin').value.trim();
  item.location = item.aisle.replace('Aisle ', '') + '-' + item.rack.replace('Rack ', '') + '-' + item.bin.replace('Bin ', '');

  if (oldOnHand !== item.onHand) {
    const diff = item.onHand - oldOnHand;
    const uName = (typeof currentActiveUser !== 'undefined' && currentActiveUser.name) ? currentActiveUser.name : 'Gil Sirimarco (CFO)';
    store.auditLog.unshift({
      id: 'LOG-' + Math.floor(Math.random()*9000 + 1000),
      timestamp: new Date().toLocaleString(),
      type: 'Manual Adjustment',
      sku: item.sku,
      location: item.location,
      qtyChange: (diff > 0 ? '+' : '') + diff,
      user: uName,
      ref: 'Inventory Count Reconciliation'
    });
  }

  saveInventoryStore(store);
  closeModal();
  showToast('💾 Updated SKU ' + item.sku);
  renderInventoryView();
}

function deleteInventoryItem(itemId) {
  if (!confirm('Are you sure you want to remove this SKU from warehouse inventory?')) return;
  const store = getInventoryStore();
  store.items = store.items.filter(i => i.id !== itemId);
  saveInventoryStore(store);
  closeModal();
  showToast('🗑️ Item deleted');
  renderInventoryView();
}

